(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fi"] = {"ui":{"skip":"Siirry sisältöön","back":"← Takaisin AI-gileen","lang.button":"Kieli: {name}","lang.dialog":"Valitse kieli","lang.search":"Hae kieliä","lang.none":"Yksikään kieli ei täsmää","lang.notYet":"{name} ei ole vielä käännetty","theme.aria":"Vaihda teema: vaalea, tumma tai musta","theme.toLight":"Vaihda vaaleaan teemaan","theme.toDark":"Vaihda tummaan teemaan","theme.toBlack":"Vaihda mustaan teemaan (aidosti musta, säästää OLED-näyttöjä)","words.underline":"Alleviivaa nämä sanat sivulla","words.underlineHelp":"Vie hiiri pisteillä alleviivatun sanan päälle tai napauta sitä, niin näet, mitä se tarkoittaa.","words.col.todo":"Tällä hetkellä valitut kortit: tiimi aloittaa näistä seuraavaksi.","words.col.doing":"AI työstää tätä korttia juuri nyt.","words.col.review":"Yksi AI on tehnyt työn; toinen tarkistaa sen ennen kuin se tulee sinulle.","words.col.verify":"Odottaa sinua: kokeile ja kerro, toimiiko se.","words.col.team":"Sinun muistiinpanosi tai vastauksesi, jotka odottavat, että tiimi poimii ne.","words.col.done":"Valmis ja hyväksytty.","index.title":"AI-gile: tekoälykehitystiimisi yhdellä taululla","index.description":"AI-gile on kanban-taulu tekoälyn kanssa koodaaville tiimeille. Ne tekevät töitä, kun nukut; sinulle jää yksi lyhyt pino päätettävää, testattavaa ja hyväksyttävää.","hero.logoAlt":"AI-gile-taulun kuvake","hero.h1.html":"Tekoälykehitystiimisi yhdellä&nbsp;taululla.","hero.alpha":"🐣 Suljettu esialfa","hero.alphaTitle":"Keskeneräinen ja aikainen: kiitos kun kokeilet!","hero.lede":"Ne rakentavat, kun nukut. Herätessäsi odottaa yksi lyhyt pino: pari kysymystä, pari testattavaa, yksi tai kaksi violettia timanttia. Klikkaus, hyväksytty, ja takaisin kahvin ääreen.","dl.windows":"Windows-sovellus","dl.browser":"Käytä selaimessa","dl.messenger":"📱 Messenger puhelimeesi","dl.soon":"Tulossa pian","dl.notify":"🔔 Kerro, kun se aukeaa","dl.notifySmall":"Alfa tai beta","hero.secondary":"Ketterää kehitystä, mutta tiimi ei koskaan tarvitse seisomapalaverin kahvia. (Seisomapalaverin se pitää silti.)","pitch.h2":"AI-gile niin monella sanalla kuin haluat","pitch.lede":"Valitse pituus yhdestä sanasta 144:ään. Jokainen pituus on oma kuvauksensa, kirjoitettu juuri sitä kokoa varten. Vedä liukusäädintä tai käytä nuolinäppäimiä.","pitch.rangeLabel":"Pituus sanoina","pitch.dice":"🎲 toinen versio","pitch.words.one":"{n} sana","pitch.words.other":"{n} sanaa","pitch.letters.one":"{n} kirjain","pitch.letters.other":"{n} kirjainta","pitch.chars.one":"{n} merkki","pitch.chars.other":"{n} merkkiä","count.line.html.one":"{n} kortti taululla juuri nyt","count.line.html.other":"{n} korttia taululla juuri nyt","people.humans.html.one":"👥 {n} ihminen","people.humans.html.other":"👥 {n} ihmistä","people.agents.html.one":"🤖 {n} agentti","people.agents.html.other":"🤖 {n} agenttia","people.working.html.one":"⚡ {n} töissä juuri nyt","people.working.html.other":"⚡ {n} töissä juuri nyt","pre.title":"AI-gile: täällä rakennetaan jotain","pre.description":"Täällä rakennetaan jotain. Taulu, jolla tekoälytiimit rakentavat, mitä pyydät, ja opettavat sinua samalla. Toistaiseksi suljettu esialfa ystävien kesken.","pre.h1":"Täällä rakennetaan jotain. 🤫","pre.line":"Taulu, jolla tekoälytiimit rakentavat, mitä pyydät, ja opettavat sinua samalla. Toistaiseksi suljettu esialfa ystävien kesken.","pre.btn":"🔔 Kerro, kun se aukeaa","pre.peek":"Lasin takana: oikea taulu, livenä. Jokainen kortti on värillinen palkki.","pre.peekFake":"Lasin takana: tältä näyttää taulu työn touhussa.","pre.night":"🌙 Yövartija pitää ohjat · 😴 ihminen lepää","features.aria":"Mitä se tekee","f.pile.h":"Yksi pino sinulle","f.pile.html":"<b>Sinulle</b> kokoaa kaiken, mikä odottaa sinua, kaikista projekteista: kysymykset, testattavat asiat ja tehtävät, jotka vain ihminen voi hoitaa. Jonosi kertoo, mikä on seuraavana ja kuinka kauan se vie.","f.sleep.h":"Tiimit, jotka tekevät töitä, kun nukut","f.sleep.p":"Jokaisella projektilla on vetäjä ja tekoälyagenttien tiimi. Kommentoi korttia, niin tiimi herää, tekee työn ja palauttaa sen ohjeineen, joita väsynytkin ihminen jaksaa seurata.","f.tester.h":"Tekoälytestaaja tarkistaa ensin","f.tester.p":"Ennen kuin mikään pääsee sinulle asti, testaaja käy ohjeet läpi sovelluksen kopiossa ja näyttää näkemänsä kuvakaappauksen kanssa. Selaa läpimenneet ja hyväksy yhdellä klikkauksella.","f.proof.h":"Todisteita, ei lupauksia","f.proof.p":"Jokainen luovutus näyttää, mikä muuttui: tiedostot, diffin ja kuvakaappaukset. Sinun ei tarvitse availla jokaista sovellusta nähdäksesi, onko työ valmis.","f.chat.h":"Juttele vetäjiesi kanssa","f.chat.p":"Discord-tyylinen palkki: yksi kuvake per projekti, violetit timantit sille, mikä tarvitsee sinua. Lähetä vetäjälle idea; hän tekee siitä kortit ja suunnitelman sekä ✅ Go-painikkeen.","f.tidy.h":"Siivoaa itse itsensä","f.tidy.p":"Toisiinsa liittyvät kortit yhdistyvät, sekavat otsikot korjataan, ja tokenien tarkistus pitää koodin kevyenä. Vähemmän vaihdettavaa, vähemmän mietittävää.","f.private.h":"Sinun, omalla koneellasi","f.private.li1":"Taulu toimii omalla koneellasi ja vastaa vain sinulle.","f.private.li2":"Ihmisten väliset yksityisviestit on salattu päästä päähän.","f.private.li3":"Ei tilejä, ei seurantaa, ei evästeitä.","f.lang.h":"Omalla kielelläsi","f.lang.p":"Yli 120 kieltä hollannista, kymristä ja japanista merirosvoon, Yodaan ja klingoniin, ja nopea paluu englantiin ammattitermejä varten.","f.service.h":"Ideasta oikeaksi palveluksi","f.service.p":"Rakensitko tekoälyn kanssa jotain, mitä ihmiset nyt käyttävät? Merkitse se palveluksi, niin taulu auttaa sinua ylläpitämään sitä hyvin: käytettävyystarkistukset, julkinen tilasivu, häiriöt ja niiden jälkipuinnit, muutokset, jotka tarvitsevat Go:n, ja päivittäin tarkistetut varmuuskopiot. Ohje opastaa jokaisen vaiheen matkan varrella.","msgr.h2":"AI-gile Messenger: tiimisi taskussa","msgr.p1":"Juttele tekoälytiimisi kanssa avaamatta taulua. Chattaile projektiesi vetäjien ja kavereidesi kanssa, katso kortin testivaiheet ja vastaa niihin, kaikki puhelimesta.","msgr.p2":"Yhdistä skannaamalla taulultasi QR-koodi. Ensimmäinen kerta? Ystävällinen demochat näyttää paikat.","msgr.when":"Ensin Android, sitten verkkoversio puhelimille ja iPhonelle.","msgr.who":"Projektisi vetäjä","msgr.b1":"Tumman tilan korjaus on valmis. Haluatko testivaiheet?","msgr.b2":"Kyllä kiitos!","msgr.b3":"1. Avaa Asetukset. 2. Valitse Tumma. Näyttääkö oikealta?","tl.aria":"Aikajana ensimmäisestä keskustelusta tiekarttaan","tl.h2":"Ensimmäisestä keskustelusta seuraaviin askeliin","tl.lede":"Oikeat päivämäärät ja kellonajat omalla aikavyöhykkeelläsi. Tämän päivän jälkeen on suunnitelma, jossa ei luvata päivämääriä.","tl.today":"Tänään","tl.planned":"suunniteltu","tl.doing":"työn alla","tl.cards.one":"{n} kortti","tl.cards.other":"{n} korttia","join.h2":"Tule mukaan","join.lede":"AI-gilea rakentaa parrakas outolintu, jolla on AuDHD ja muutama kamppailu mielenterveyden kanssa, sekä suuri joukko kärsivällisiä agentteja. Se on toistaiseksi yksityinen, suljettu alfa kavereiden kesken. Haluatko kokeilla, kun se aukeaa?","join.btn":"Ilmoita kiinnostuksesi","join.small":"Lähetämme sähköpostia, emme muuta","footer.tag":"AI-gile. Ei seurantaa, ei evästeitä, ei seisomapalaverin kahvia.","footer.licence":"Yrityslisenssi","footer.status":"Tila","footer.privacy":"Mitä säilytämme","footer.thanks":"Puhelut ChilledChatin ansiosta","form.sending":"Lähetetään…","form.failed":"Se ei onnistunut: yritä myöhemmin uudelleen.","form.offline":"AI-gileen ei saatu yhteyttä: yritä myöhemmin uudelleen.","form.keep":"Käytämme tätä vain vastataksemme sinulle, sitten poistamme sen. Ei seurantaa, ei evästeitä.","form.keepLink":"Mitä säilytämme","interest.title":"AI-gile: kerro, kun alfa aukeaa","interest.description":"Jätä sähköpostisi, niin kuulet, kun AI-gilen suljettu alfa tai beta aukeaa.","interest.h1":"🔔 Kerro, kun se aukeaa","interest.lede":"AI-gile on suljetussa esialfassa. Jätä sähköpostisi, niin kirjoitamme kerran, kun sinulle on paikka.","interest.email":"Sähköpostisi","interest.which":"Mikä testi?","interest.alpha":"Suljettu alfa: aikainen, kulmikas, paljon muutoksia","interest.beta":"Beta: vakaampi, myöhemmin","interest.both":"Kumpi vain, kumpi aukeaa ensin","interest.submit":"Lisää minut listalle","interest.thanks":"Kiitos! Olet listalla.","licence.title":"AI-gile: yrityslisenssi","licence.description":"Käytätkö AI-gilea yrityksessäsi? Hae ilmaista yrityslisenssiä.","licence.h1":"📜 Yrityslisenssi","licence.lede":"Käytätkö AI-gilea töissä? Kerro, keitä olette ja mitä teette. Jos siitä on hyötyä, lisenssi on ilmainen.","licence.company":"Yritys","licence.website":"Verkkosivusto","licence.what":"Mitä teette","licence.how":"Miten se auttaa maailmaa","licence.email":"Sähköposti","licence.submit":"Hae","licence.thanks":"Kiitos! Vastaamme sähköpostilla.","status.title":"AI-gilen tila","status.h1":"AI-gilen tila","status.quiet":"Kaikki hiljaista","status.intro":"Toimiiko AI-gile juuri nyt? Tämä sivu tarkistaa 5 minuutin välein verkkosivuston, taulujen jakamisen, puhelut ja latauksen.","status.up":"Toimii (vastasi {ms} ms:ssa)","status.slow":"Ei vastannut viime tarkistukseen, yritetään uudelleen","status.down":"Alhaalla: ei vastannut kahteen viime tarkistukseen","status.svc.web":"Verkkosivusto","status.svc.web.offers":"Tämä sivusto: mikä AI-gile on, ja kiinnostuslomake","status.svc.boards":"Taulujen jakaminen","status.svc.boards.offers":"Julkiset taulut, viestit ystävien kesken ja kutsut","status.svc.calls":"Puhelut","status.svc.calls.offers":"Ääni, video ja näytön jakaminen AI-gilessä","status.svc.download":"Lataus","status.svc.download.offers":"Windows-asennusohjelma ja kutsulinkit","status.checking":"Tarkistetaan…","status.offline":"Tilapalveluun ei saada juuri nyt yhteyttä (yritetään uudelleen)","status.updated":"päivitetty {ago}","status.justNow":"juuri nyt","status.min":"{n} min sitten","status.hours":"{n} t sitten","status.days":"{n} pv sitten","privacy.title":"AI-gile: mitä säilytämme","privacy.h1":"Mitä säilytämme","privacy.lede":"Lyhyesti: vain sen, minkä lähetät meille, eikä kauan.","privacy.only":"Vain sen, minkä lähetät meille: mitä kirjoitat lomakkeeseen, kuten sähköpostiosoitteesi. Ei mitään muuta sinusta.","privacy.sealed":"Se sinetöidään, jotta palvelimemme ei voi lukea sitä: selaimessasi ennen kuin se lähtee (vanhemmassa selaimessa heti kun se saapuu). Vain oma taulumme voi avata sen.","privacy.server":"Se poistetaan palvelimelta heti, kun se saapuu taulullemme. Kaikki, mikä on siellä yhä 30 päivän jälkeen, poistetaan joka tapauksessa.","privacy.board":"Säilytämme sitä taulullamme vain siihen asti, kunnes olemme vastanneet sinulle, ja poistamme sen sitten sieltäkin.","privacy.none":"Ei seurantaa, ei evästeitä, ei analytiikkaa.","privacy.local":"Kielesi ja vaalean tai tumman tilan valintasi pysyvät omassa selaimessasi. Niitä ei koskaan lähetetä meille.","privacy.ask":"Haluatko, että se poistetaan aiemmin? Vastaa sähköpostiimme ja kerro siitä.","live.h2":"Katso, kun sitä rakennetaan, livenä","live.caption":"Jokainen kortti on piilotettu: näet työn muodon, et sanoja.","live.watching.one":"livenä: {n} katsoo","live.watching.other":"livenä: {n} katsoo","live.last.now":"Viimeisin kortti siirrettiin juuri nyt","live.last.min.one":"Viimeisin kortti siirrettiin {n} min sitten","live.last.min.other":"Viimeisin kortti siirrettiin {n} min sitten","live.last.hour.one":"Viimeisin kortti siirrettiin {n} tunti sitten","live.last.hour.other":"Viimeisin kortti siirrettiin {n} tuntia sitten","live.last.day.one":"Viimeisin kortti siirrettiin {n} päivä sitten","live.last.day.other":"Viimeisin kortti siirrettiin {n} päivää sitten","live.offline":"Live-taulu pitää pienen tauon. Käy katsomassa pian uudelleen.","live.cols":"Backlog|Tehtävänä|Työn alla|Tiimi tarkistaa|Sinun testattavasi|Tiimille|Valmis","footer.models":"AI-gile panee tekoälymallit töihin puolestasi. Se, mitä ne sanovat ja tekevät, on niiden omaa, joten tarkista se, ennen kuin luotat siihen.","privacy.ai.h":"Tekoälyosuus","privacy.ai.models":"AI-gile on taulu. Työn tekevät muiden yritysten tekoälymallit, kuten Claude, Codex ja Gemini, omilla tileilläsi.","privacy.ai.check":"Se, mitä ne kirjoittavat ja tekevät, tulee niiltä, ja se voi olla väärin. Tarkista se, ennen kuin turvaudut siihen tai julkaiset sen.","privacy.ai.files":"Ne muuttavat tiedostoja ja ajavat komentoja kansioissa, jotka yhdistät. Ota varmuuskopio.","privacy.ai.send":"Se, minkä annat mallille, menee sen pyörittäjälle yritykselle sen ehdoilla. Kunkin omat ehdot ja kustannukset pätevät.","privacy.ai.asis":"AI-gile on varhainen testiversio, sellaisena kuin se on."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotit.","Delegoitu."]},{"n":2,"texts":["Robotit tekevät.","Agentit töihin.","Ideat valmiiksi."]},{"n":3,"texts":["Kanban robooteille.","Ideasta ominaisuus.","Ilmainen agenttikanban."]},{"n":5,"texts":["Agentit pyörittävät sinun kanban-taulua.","Sinä kirjoitat, agentit rakentavat.","Ilmainen, paikallinen, testattu, hieman hassu."]},{"n":8,"texts":["Ilmainen kanban-taulu, jolla tekoälyagentit tekevät töitä.","Kirjoita idea. Agentit rakentavat. Sinä hyväksyt.","Ketterää kehitystä yhdelle ihmiselle ja monelle kärsivälliselle robotille."]},{"n":13,"texts":["Kanban-taulu omalla koneellasi, jossa tekoälyagentit ottavat kortit hoitaakseen ja tekevät ne.","Kirjoita idea. Agenttien tiimi rakentaa sen ja testaaja tarkistaa, että se toimii.","Ilmainen, ei tilejä, ei seurantaa: yksi taulu, joukko robotteja ja sinä pomona."]},{"n":21,"texts":["AI-gile on kanban-taulu, jolla työskentelet tekoälykoodausagenttien kanssa. Ne ottavat kortit hoitaakseen ja tekevät työn; sinä vain testaat ja hyväksyt.","Jokaiselle projektille tulee oma vetäjä ja oma tekoälyagenttien tiimi. Kun kommentoit mitä tahansa korttia, tiimi herää ja ryhtyy heti töihin.","Ilmainen ja henkilökohtainen tehtävätaulu, joka toimii kokonaan omalla koneellasi. Työt tekevät robotit, mutta kyllä-sanojana olet aina sinä."]},{"n":34,"texts":["Laitat ideasi taululle yksi kerrallaan. Tekoälyagenttien tiimi muuttaa ne toimiviksi ominaisuuksiksi, testaa ne ja palauttaa ne sinulle ohjeineen, joilla pääset kokeilemaan. Mikään ei ole valmista ennen kuin sinä niin sanot.","AI-gile on kotitekoinen kanban-taulu, jonka Rich rakensi saaden paljon apua juuri niiltä agenteilta, joita se nyt hallitsee. Se on ilmainen, toimii omalla koneellasi ja jaetaan kavereille. Sitä ei myydä kenellekään.","Kuvittele ihan tavallinen kanban-taulu, jonka sarakkeet kulkevat Backlogista aina Valmiiksi, paitsi että kortit ottavat hoitaakseen tekoälyagentit. Ne kertovat edistymisestään, kysyvät neuvoa jumiutuessaan ja odottavat aina sinun lupaasi."]},{"n":55,"texts":["AI-gile on kanban-taulu, jonka tiimi koostuu tekoälyagenteista. Jokaisella projektilla on vetäjä, joka suunnittelee työn, sekä auttajia, jotka rakentavat sen. Kun ominaisuus on valmis, tekoälytestaaja kokeilee sitä ja ottaa kuvakaappauksen. Sitten se putoaa sinun omaan pinoosi. Hyväksy se tai kirjoita kommentti, niin agentit tekevät sen uusiksi.","Se alkoi yhden ihmisen keinona pysyä perillä monesta tekoälykoodausistunnosta yhtä aikaa, ja kasvoi vähitellen kunnolliseksi tauluksi. Se toimii omalla koneellasi, ei vaadi tiliä eikä seuraa sinua mitenkään. Se on ilmainen kavereille ja kaikille uteliaille. Se on myös vielä keskeneräinen, joten varaudu särmiin ja pieniin yllätyksiin.","Tässä rehellinen versio. Ideat sinun täytyy yhä keksiä itse, ja tulokset sinun täytyy yhä tarkistaa itse. AI-gile hoitaa kaiken siltä väliltä: se pitää kortit järjestyksessä, herättää oikean agentin, kun kommentoit, näyttää tarkasti mitä on muuttunut ja kokoaa kaiken yhteen lyhyeen pinoon, jonka sinä käyt läpi."]},{"n":89,"texts":["AI-gile on ilmainen kanban-taulu, jota pyörität omalla koneellasi. Ihmisten sijaan jokaisella projektilla on tekoälyagenttien tiimi: vetäjä, joka muuttaa ideasi korteiksi ja suunnitelmaksi, sekä auttajat, jotka ottavat kortit hoitaakseen tärkeysjärjestyksessä. Kun jotain on rakennettu, tekoälytestaaja käy testiohjeet läpi ja näyttää sinulle, mitä se näki. Sen jälkeen työ odottaa yhdessä pinossa, jonka nimi on Sinulle. Voit hyväksyä sen, tai voit kirjoittaa kommentin, jolloin tiimi yrittää uudelleen. Mikään ei koskaan päädy sarakkeeseen Valmis ilman sinua.","Tässä muutama ominaisuus, joita et ehkä osaa odottaa. Yövahti pitää Tehtävänä-sarakkeen täynnä sillä aikaa, kun nukut, ja valitsee kortteja, jotka eivät tarvitse sinun vastaustasi. Tokenilaskuri näyttää, kuinka paljon agentit ovat käyttäneet tänään ja tällä viikolla, ja Ei tokeneita -tila käskee niitä lopettamaan kuluttamisen. Voit lähettää viestejä kavereille, ja yksityisviestit on salattu päästä päähän. Taulu puhuu noin 120 kieltä, esimerkiksi hollantia, flaamia, merirosvoa ja klingonia. Mikään tästä ei maksa penniäkään, eikä kukaan yritä myydä sitä sinulle.","AI-gile on pieni henkilökohtainen projekti eikä mikään yritys. Rich halusi pitää huolta useasta tekoälykoodausprojektista ilman, että hänen pitää availla jokaista sovellusta erikseen tarkistaakseen tilanteen. Niinpä hän ja agentit rakensivat tätä varten taulun ja käyttivät sitä sitten loppuosan rakentamiseen. Se on suljetussa esialfassa, mikä tarkoittaa, että se toimii enimmäkseen, ja vain kourallisella kavereita. Hinnastosivua, uutiskirjettä tai kasvusuunnitelmaa ei ole. Jos tämä kuulostaa hyödylliseltä, voit pyytää päästä kokeilemaan, kun se aukeaa vähän laajemmalle."]},{"n":144,"texts":["AI-gile on kanban-taulu yhdelle ihmiselle ja monelle tekoälyagentille. Se toimii omalla koneellasi ja on täysin ilmainen. Lisäät taululle projekteja, ja jokaiselle projektille tulee oma vetäjä ja pieni tiimi. Juttelet vetäjän kanssa vähän Discordin tapaan ja kerrot idean. Vetäjä muuttaa sen korteiksi ja suunnitelmaksi ja odottaa sitten, että painat Go-painiketta. Tiimi käy kortit läpi tärkeysjärjestyksessä käyttäen yksinkertaista komentoriviä, joka on tehty nimenomaan kielimalleja varten. Ennen kuin mikään palaa sinulle, tekoälytestaaja käy ohjeet läpi sovelluksen kopiossa ja liittää mukaan kuvakaappauksen. Valmis työ päätyy sinun pinoosi, ja mukana ovat muuttuneet tiedostot sekä diff. Voit hyväksyä työn, tai voit jättää kommentin, jolloin tiimi herää ja yrittää uudelleen. Vain sinä voit siirtää kortin sarakkeeseen Valmis. Mitään ei siis tapahdu selkäsi takana, eikä mikään ole valmista, ennen kuin olet itse katsonut sitä.","Päivä AI-gilen kanssa, suunnilleen näin. Illalla jätät muutaman kommentin: tämä painike on väärässä paikassa, tuo lista pitäisi lajitella, voisiko tähän saada tumman teeman. Sitten menet nukkumaan. Agentit lukevat kommentit, tekevät muutokset, testaavat ne ja palauttavat ne sinulle. Jos Tehtävänä-sarake alkaa tyhjentyä, yövahti täyttää sen backlogista korteilla, jotka eivät tarvitse sinun vastaustasi. Aamulla odottaa yksi lyhyt pino: pari kysymystä ja muutama kokeiltava asia, jokaisessa mukana ohjeet, joita unelias ihminen jaksaa seurata, sekä kuvakaappaus siitä, että homma toimii. Klikkailet pinon läpi, hyväksyt hyvät ja lähetät loput takaisin. Tokenilaskuri näyttää, paljonko kaikki tämä kulutti, ja Ei tokeneita -tila on olemassa laihoja viikkoja varten. Sitten syöt aamiaista, jossa agentit eivät vielä osaa auttaa. Ja sinä saat vielä kahvia ihan rauhassa.","Ensin se, mitä AI-gile ei ole. Se ei ole startup, se ei ole myytävänä, eikä kukaan kerää sinun tietojasi. Se on ilmainen taulu, joka toimii omalla koneellasi ilman tilejä, ilman seurantaa ja ilman evästeitä. Mikä se sitten on: yksi siisti paikka, jossa näet kaikki tekoälykoodausprojektisi kerralla, agenttien tiimi hoitamassa kortteja ja sinä tekemässä päätökset. Se yhdistää toisiinsa liittyvät kortit, korjaa sekavat otsikot ja pitää silmällä, pysyykö koodi kevyenä. Se puhuu noin 120 kieltä, hollannista ja flaamista aina merirosvoon ja klingoniin asti. Kaverit voivat lähettää toisilleen viestejä, yksityisesti ja salattuna. Sen ovat rakentaneet Rich ja suuri joukko kärsivällisiä agentteja, enimmäkseen sitä itseään käyttäen. Se on suljetussa esialfassa, joten se on paikoin vielä kulmikas. Jos tämä kuulostaa hauskalta, pyydä kauniisti, niin pääset ehkä mukaan jo aikaisin."]}],"quips":{"1":"Yksi sana. Rohkea. Ehkä liiankin.","3":"Kolme sanaa. Jo rehellisempi kuin useimmat tuotesivut.","8":"Kahdeksan sanaa. Vielä lyhyempi kuin seisomapalaveri.","21":"Pituudet ovat muuten story pointteja. Tietysti ovat.","55":"Viisikymmentäviisi sanaa. Kaksi korttia valmistui, kun luit tämän.","144":"Tämä oli pisin. 233:a ei ole. Agentit ovat menneet nukkumaan."}},"timeline":{"first-idea.name":"Ensimmäinen idea","first-idea.line":"Aivan ensimmäinen keskustelu, ennen kuin koodia oli olemassa.","first-board.name":"Ensimmäinen taulu","first-board.line":"Taulu, joka seuraa oman rakentamisensa etenemistä: kortit, sarakkeet, vedä ja pudota, projektit.","team-roles.name":"Tiimi ja roolit","team-roles.line":"Agenttiprofiilit, tiimipohjat, tilat ja se, kuka tekee mitä.","install.name":"Asennus ja julkaisut","install.line":"Zip, jonka kaveri osaa asentaa, itsepäivitys, kanavat ja paluu vanhaan versioon.","usage-saver.name":"Käytönsäästäjä","usage-saver.line":"Mittaa, mitä ajot maksavat, pidä koodi kevyenä ja säästä rajasi.","friends.name":"Kaverit ja jakaminen","friends.line":"Yksityisviestit, sekoitettu välitys, kutsut, roolit ja jaetut projektit.","languages.name":"Kielet","languages.line":"Jokainen näytön teksti kielitiedostossa, hollanti ja flaami ensin.","ai-tester.name":"Tekoälytestaaja","ai-tester.line":"Testaaja tarkistaa jokaisen luovutuksen ensin ja näyttää näkemänsä.","website.name":"Verkkosivusto","website.line":"aigile.lol, esittelysivu ja tämä aikajana.","streaming.name":"Chat ja striimaus","streaming.line":"Discord, Twitch, OBS, striimaajatila, GIFit ja emojit.","no-ai.name":"Ilman tekoälyä -versio","no-ai.line":"Taulu ihmisille, jotka koodaavat ilman tekoälyä, sekä julkiset taulut.","night-watch.name":"Yövahti","night-watch.line":"Vahtimies ja Scrum Master pitävät tiimit tehtävässään, kun nukut.","p-more.name":"Kaikki muu","p-more.line":"Pienempiä ideoita, jotka odottavat vielä vuoroaan.","p-android.name":"Puhelin ja Android","p-android.line":"Taulusi puhelimella, sitten natiivi Android-sovellus.","p-release.name":"Alfa ja sen jälkeen","p-release.line":"Suljettu alfa, sivusto verkkoon, sitten beta.","p-languages.name":"Lisää kieliä","p-languages.line":"130 kieltä ja kielikylpytila oppijoille.","p-engines.name":"Lisää tekoälymoottoreita","p-engines.line":"Valitse jokaiselle agentille Claude, Codex, Gemini, Copilot tai Cursor.","p-pro.name":"Ammattikäytännöt","p-pro.line":"Riskimerkinnät, yhdistämisportit, häiriökortit ja suojakaiteet.","p-self.name":"Sinusta huolehtiminen","p-self.line":"Väsynyt-tila, itsehoitomuistutukset ja 4:20.","p-servers.name":"Palvelimet ja skaalaus","p-servers.line":"Yleiset palvelinasetukset, roolit ja kasvun suunnittelu.","p-livestream.name":"Striimauksen lisät","p-livestream.line":"Twitch-chat, omat emojit ja julkinen suoranäkymä."},"words":{"button":"📖 Ammattitermit","h":"📖 Sanat selitettynä","intro":"Ilmainen koulutus selkeällä kielellä: jokainen sana, johon törmäät ensimmäisestä ideasta aina palveluun, johon ihmiset luottavat. Matkan varrella tutuiksi tulevat ketteryys, rakentaminen, turvallisuus ja työskentely tekoälyn kanssa.","search":"Hae sanaa…","none":"Mikään sana ei täsmää.","close":"Sulje","count":{"one":"{count} sana","other":"{count} sanaa"},"groups":[{"id":"idea","name":"💡 Idea ja selvitys"},{"id":"plan","name":"🗺️ Työn suunnittelu"},{"id":"agile","name":"🔁 Ketterät työtavat"},{"id":"build","name":"🛠️ Rakentaminen"},{"id":"test","name":"🧪 Testaus ja laatu"},{"id":"change","name":"🔀 Turvallinen muuttaminen"},{"id":"run","name":"🛎️ Palvelun ylläpito"},{"id":"sec","name":"🔒 Tietoturva ja yksityisyys"},{"id":"ai","name":"🤖 Työskentely tekoälyn kanssa"},{"id":"money","name":"💰 Raha ja lisenssit"}],"list":[{"id":"discovery","g":"idea","word":"Selvitysvaihe (discovery)","text":"Alkuvaihe, jossa selvitetään, mikä ongelma kannattaa ratkaista ja kenelle, ennen kuin mitään rakennetaan.","also":["discovery","discovery phase","selvitysvaihe","selvitysvaiheen","selvitysvaiheessa"]},{"id":"problemstmt","g":"idea","word":"Ongelmakuvaus","text":"Yksi tai kaksi lausetta, jotka kertovat, kenellä on ongelma, mikä se on ja miksi sillä on väliä, jotta kaikki tähtäävät samaan asiaan.","also":["ongelmakuvaukset","problem statement","problem statements","ongelmakuvauksen","ongelmakuvausta"]},{"id":"user","g":"idea","word":"Käyttäjä","text":"Henkilö, joka käyttää sitä, mitä rakennat. Työ tehdään heidän tarpeitaan varten.","also":["käyttäjät","käyttäjän","user","users","käyttäjää","käyttäjille"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Sidosryhmä","text":"Kuka tahansa, jolle työn lopputulos on tärkeä tai johon se vaikuttaa, esimerkiksi ne, jotka maksavat siitä, käyttävät sitä tai tukevat sitä.","also":["sidosryhmät","sidosryhmän","stakeholder","stakeholders","sidosryhmää","sidosryhmien","sidosryhmille"]},{"id":"persona","g":"idea","word":"Persoona","text":"Kuviteltu mutta uskottava henkilö, joka edustaa yhtä käyttäjätyyppiä, jotta tiimi voi kysyä: ”Olisiko tämä Samille helppoa?”","also":["persoonat","persona","personas","persoonan","persoonaa"]},{"id":"userresearch","g":"idea","word":"Käyttäjätutkimus","text":"Oikeiden ihmisten haastattelemista ja havainnointia, jotta opitaan, mitä he tarvitsevat, arvaamisen sijaan.","also":["käyttäjähaastattelut","user research","user interviews","käyttäjätutkimuksen","käyttäjätutkimusta"]},{"id":"journey","g":"idea","word":"Käyttäjän polku","text":"Vaiheet, jotka ihminen käy läpi saadakseen jotain tehtyä, siitä kun hän ensi kerran kuulee asiasta siihen, kun se on valmis, myös tuotteesi ulkopuolella. Kun polun piirtää auki, näkee, mihin ihmiset jumittavat.","also":["käyttäjäpolku","asiakaspolku","user journey","user journeys","customer journey","käyttäjän polun","käyttäjäpolun","asiakaspolun"]},{"id":"painpoint","g":"idea","word":"Kipupiste","text":"Jokin, mikä ärsyttää tai hidastaa ihmisiä nykyisin. Hyvät tuotteet poistavat kipupisteitä.","also":["kipupisteet","pain point","pain points","kipupisteen","kipupistettä","kipupisteitä"]},{"id":"assumption","g":"idea","word":"Oletus","text":"Jotain, mitä uskot mutta et ole vielä tarkistanut. Kun oletukset kirjoittaa ylös, näkee, mitä pitää testata ensin.","also":["oletukset","oletuksen","assumption","assumptions","oletusta","oletuksia"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypoteesi","text":"Paras arvauksesi, jonka aiot tarkistaa, ja mitä odotat tapahtuvan, esimerkiksi ”ihmiset rekisteröityvät, jos ensimmäinen kuukausi on ilmainen”.","also":["hypoteesit","hypothesis","hypotheses","hypoteesin","hypoteesia"]},{"id":"experiment","g":"idea","word":"Kokeilu","text":"Pieni suunniteltu testi, jolla selvitetään, toimiiko idea, ennen kuin siihen panostetaan paljon.","also":["kokeilut","koe","experiment","experiments","kokeilun","kokeilua"],"noTip":1},{"id":"poc","g":"idea","word":"Konseptin todistus (PoC)","text":"Nopea ja karkea yritys nähdä, voiko idea ylipäätään toimia. Se heitetään yleensä pois, kun vastaus on selvillä.","also":["PoC","proof of concept","konseptitodiste","konseptin todistus","konseptin todistuksen"]},{"id":"prototype","g":"idea","word":"Prototyyppi","text":"Tuotteen varhainen malli, usein klikattavia kuvia, jolla ideaa kokeillaan ihmisillä ennen kuin se rakennetaan kunnolla.","also":["prototyypit","prototype","prototypes","prototyypin","prototyyppiä"]},{"id":"wireframe","g":"idea","word":"Rautalankamalli (wireframe)","text":"Yksinkertainen luonnos näkymästä, joka näyttää, mihin mikin tulee, ilman värejä tai oikeaa sisältöä.","also":["wireframe","wireframes","rautalankamallit","rautalankamalli","rautalankamallin","rautalankamallia"]},{"id":"mockup","g":"idea","word":"Mallinäkymä (mockup)","text":"Yksityiskohtainen kuva siitä, miltä näkymä tulee näyttämään, oikeine värein ja teksteineen, mutta mikään ei vielä toimi.","also":["mockup","mockups","mock-up","mock-ups","mallinäkymät","mallinäkymä","mallinäkymän"]},{"id":"bizcase","g":"idea","word":"Liiketoimintaperustelu","text":"Syyt projektin tekemiseen: mitä se maksaa, mitä se tuo tai säästää ja mitkä ovat riskit.","also":["liiketoimintaperustelut","liiketoimintaperustelun","liiketoimintaperustelua","business case","business cases"]},{"id":"feasibility","g":"idea","word":"Toteutettavuus","text":"Voiko jotain todella rakentaa ja ylläpitää sillä ajalla, rahalla ja osaamisella, joka on käytettävissä.","also":["feasibility","toteutettavissa","toteutettavuuden","toteutettavuutta"]},{"id":"outcome","g":"idea","word":"Vaikutus (outcome)","text":"Muutos, jonka haluat ihmisille, kuten vähemmän unohtuneita aikoja. Se on tärkeämpää kuin se, kuinka paljon rakennat.","also":["vaikutukset","tulos","outcome","outcomes","vaikutuksen","vaikutusta"],"noTip":1},{"id":"output","g":"idea","word":"Tuotos (output)","text":"Jotain, mitä tiimi tekee, kuten uusi näkymä tai raportti. Se, että jokin on tehty, ei automaattisesti tarkoita, että siitä on apua kenellekään.","also":["tuotokset","output","outputs","tuotoksen","tuotosta"],"noTip":1},{"id":"successmetric","g":"idea","word":"Menestysmittari","text":"Luku, joka kertoo, saavuttiko työ sen, mitä varten se tehtiin, esimerkiksi se, että useampi saa tilauksensa tehtyä loppuun.","also":["menestysmittarit","success metric","success metrics","menestysmittarin","menestysmittaria"]},{"id":"kpi","g":"idea","word":"Keskeinen suorituskykymittari (KPI)","text":"Tärkeä luku, jota seuraat nähdäksesi, menevätkö asiat hyvin, esimerkiksi rekisteröitymiset viikossa.","also":["KPI","KPI:t","KPI:n","KPI:tä","avainluku","avainluvut","key performance indicator"]},{"id":"okr","g":"idea","word":"Tavoitteet ja avaintulokset (OKR)","text":"Tapa asettaa tavoitteita: tavoite kertoo, mitä haluat, ja muutama avaintulos kertoo luvuin, että pääsit perille.","also":["OKR","OKR:t","objectives and key results","OKR:n","OKR:iä"]},{"id":"product","g":"plan","word":"Tuote","text":"Se, mitä käyttäjiä varten rakennetaan ja ylläpidetään, kuten sovellus, verkkosivusto tai työkalu.","also":["tuotteet","tuotteen","product","products","tuotetta"],"noTip":1},{"id":"vision","g":"plan","word":"Tuotevisio","text":"Lyhyt kuvaus siitä, ketä tuote auttaa ja minne se on pitkällä aikavälillä menossa.","also":["visiolausuma","vision statement","tuotevision","tuotevisiota"]},{"id":"po","g":"plan","word":"Tuoteomistaja (PO)","text":"Henkilö, joka päättää, mitä rakennetaan ja missä järjestyksessä, jotta tiimi tekee aina tärkeintä. AI-gilessä se olet sinä.","also":["PO","product owner","product owners","tuoteomistajat","tuoteomistajan","tuoteomistajaa"]},{"id":"pm","g":"plan","word":"Tuotepäällikkö (PM)","text":"Henkilö, joka huolehtii tuotteen suunnasta: mitä ongelmia se ratkaisee, kenelle ja miksi. PM voi tarkoittaa myös projektipäällikköä, joten tarkista kumpi.","also":["PM","product manager","product managers","tuotevastaava","tuotepäällikön","tuotepäällikköä"]},{"id":"projmgr","g":"plan","word":"Projektipäällikkö","text":"Henkilö, joka pitää projektin aikataulussa ja budjetissa ja seuraa, kuka tekee mitä ja milloin.","also":["projektipäälliköt","project manager","project managers","projektipäällikön","projektipäällikköä"]},{"id":"roadmap","g":"plan","word":"Tiekartta","text":"Karkea suunnitelma siitä, mitä tulevina kuukausina on tulossa, järjestyksessä. Se näyttää suunnan, ei tarkkoja päivämääriä, ja muuttuu sitä mukaa kun opit.","also":["tiekartat","roadmap","roadmaps","tiekartan","tiekarttaa"]},{"id":"milestone","g":"plan","word":"Virstanpylväs","text":"Projektin kohta, joka kannattaa merkitä, kuten ”ensimmäinen versio käytössä” tai ”100 käyttäjää”.","also":["virstanpylväät","milestone","milestones","virstanpylvään","virstanpylvästä"]},{"id":"mvp","g":"plan","word":"Minimikelpoinen tuote (MVP)","text":"Tuotteen pienin versio, josta on silti hyötyä oikeille ihmisille, jotta voit oppia heiltä jo varhain.","also":["MVP","MVP:t","minimum viable product","MVP:n","MVP:tä"]},{"id":"requirement","g":"plan","word":"Vaatimus","text":"Jotain, mitä valmiin tuotteen täytyy tehdä tai olla.","also":["vaatimukset","vaatimuksen","requirement","requirements","vaatimusta","vaatimuksia"],"noTip":1},{"id":"scope","g":"plan","word":"Laajuus (scope)","text":"Se, mikä kuuluu työhön, ja yhtä tärkeää, se, mikä ei kuulu.","also":["scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Laajuuden hiipiminen (scope creep)","text":"Kun työhön lisätään vähitellen yhä enemmän ilman, että kukaan sopii lisäajasta tai -kustannuksista, joten työ ei koskaan oikein valmistu.","also":["scope creep","feature creep","laajuusryömintä"]},{"id":"feature","g":"plan","word":"Ominaisuus","text":"Yksi asia, jonka tuote voi tehdä ihmisten hyväksi, kuten ”nollaa salasanasi”.","also":["ominaisuudet","feature","features","ominaisuuden","ominaisuutta","ominaisuuksia"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Iso työkokonaisuus, joka on liian suuri tehtäväksi yhdellä kertaa, joten se jaetaan pienempiin kortteihin.","also":["epicit","epics","epicin","epiciä"]},{"id":"story","g":"plan","word":"Käyttäjätarina","text":"Pieni työ kirjoitettuna käyttäjän näkökulmasta: ”Ostajana haluan tallentaa ostoskorini, jotta voin viimeistellä tilauksen myöhemmin.” Se aloittaa keskustelun siitä, mitä rakennetaan.","also":["käyttäjätarinat","user story","user stories","käyttäjätarinan","käyttäjätarinaa","käyttäjätarinoita"]},{"id":"ac","g":"plan","word":"Hyväksymiskriteerit (AC)","text":"Tarkistukset, jotka yhden kortin on läpäistävä, jotta se lasketaan valmiiksi, sovittu ennen työn alkua, esimerkiksi ”ostoskori on yhä tallessa, kun kirjaudun ulos ja takaisin sisään”.","also":["AC","acceptance criteria","hyväksymisehdot","hyväksymiskriteeri","hyväksymiskriteerien","hyväksymiskriteerejä"]},{"id":"task","g":"plan","word":"Tehtävä","text":"Yksittäinen työ, joka pitää tehdä, usein yksi pieni askel isommassa tarinassa.","also":["tehtävät","tehtävän","task","tasks","tehtävää"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiketti","text":"Toinen sana kortille: yksi työ tai yksi pyyntö, jota seurataan alusta loppuun.","also":["tiketti","tiketit","ticket","tickets","tiketin","tikettiä"]},{"id":"priority","g":"plan","word":"Prioriteetti","text":"Kuinka tärkeää tai kiireellistä jokin on muuhun verrattuna, jotta tärkein työ tehdään ensin.","also":["prioriteetit","tärkeysjärjestys","priority","priorities","prioriteetin","prioriteettia"],"noTip":1},{"id":"prioritise","g":"plan","word":"Priorisointi","text":"Työn laittamista tärkeysjärjestykseen. Yleinen tapa on MoSCoW: Must have, Should have, Could have, Won’t have tällä kertaa.","also":["priorisoida","priorisoi","MoSCoW","priorisoinnin","priorisointia"]},{"id":"estimate","g":"plan","word":"Arvio","text":"Paras arvaus siitä, kuinka suuri tai pitkä työ on. Se on arvaus, ei lupaus.","also":["arviot","arviointi","estimate","estimates","estimation","arvion","arviota"],"noTip":1},{"id":"storypoints","g":"plan","word":"Tarinapisteet (story points)","text":"Tapa arvioida työn kokoa vertaamalla kortteja toisiinsa (”suunnilleen kaksi kertaa niin iso kuin tuo”) tuntien sijaan. Niillä ei ole tarkoitus verrata tiimejä.","also":["story points","story point","tarinapiste","tarinapisteet","tarinapisteitä"]},{"id":"tshirt","g":"plan","word":"T-paitakoot","text":"Työn koon arviointi kokoina S, M, L tai XL. Nopea ja riittävän hyvä alkuvaiheen suunnitteluun.","also":["t-paitakoko","T-shirt sizing","t-shirt sizes","t-paitakoot","t-paitakokoja"]},{"id":"poker","g":"plan","word":"Suunnittelupokeri","text":"Arviointipeli: kaikki näyttävät kokokortin yhtä aikaa, ja sitten suurimman ja pienimmän valinneet kertovat perustelunsa.","also":["Scrum-pokeri","planning poker","Scrum poker","suunnittelupokerin","suunnittelupokeria"]},{"id":"dependency","g":"plan","word":"Riippuvuus","text":"Kun yksi työ ei voi alkaa tai valmistua ennen kuin toinen on valmis.","also":["riippuvuudet","dependency","dependencies","riippuvuuden","riippuvuutta","riippuvuuksia"]},{"id":"blocker","g":"plan","word":"Este (blocker)","text":"Mikä tahansa, mikä estää työtä etenemästä juuri nyt, kuten puuttuva vastaus tai rikkinäinen työkalu.","also":["blocker","blockers"]},{"id":"deadline","g":"plan","word":"Määräaika","text":"Päivämäärä, johon mennessä jonkin on oltava valmis.","also":["määräajat","deadline","deadlines","takaraja","määräajan","määräaikaa","takarajan"],"noTip":1},{"id":"deliverable","g":"plan","word":"Toimitus","text":"Jotain konkreettista, minkä työ tuottaa ja luovuttaa eteenpäin, kuten toimiva sivu tai raportti.","also":["deliverable","deliverables","luovutettava tuotos"]},{"id":"forecast","g":"plan","word":"Ennuste","text":"Ennuste siitä, mitä todennäköisesti tapahtuu, esimerkiksi milloin työ valmistuu, sen perusteella, mitä tähän mennessä tiedät.","also":["ennusteet","forecast","forecasts","ennusteen","ennustetta"],"noTip":1},{"id":"metric","g":"plan","word":"Mittari","text":"Mikä tahansa, mitä mittaat ja seuraat ajan mittaan, kuten sivukäynnit tai se, kuinka kauan korjaus kestää.","also":["metric","metrics"]},{"id":"feedback","g":"plan","word":"Palaute","text":"Se, mitä ihmiset kertovat työstäsi, hyvässä ja pahassa. Palautteen saaminen varhain ja usein on ketteryyden ydin.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Odotuslista ideoista ja töistä, joita ei ole vielä suunniteltu mukaan, tärkein ylimpänä. Niille ei tehdä mitään, ennen kuin ne siirtyvät sarakkeeseen Tehtävänä."},{"id":"sprint","g":"agile","word":"Sprintti","text":"Lyhyt, kiinteä työjakso (usein viikko tai kaksi, ei koskaan yli kuukautta), jolla on tavoite ja sovittu joukko kortteja valmiiksi saatettavaksi.","also":["sprintit","sprintin","sprintissä","sprint","sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Nopea päivittäinen tilannekatsaus: mitä kukin tiimin jäsen teki, mitä hän tekee seuraavaksi ja mikä häntä estää. Scrumissa sitä kutsutaan päivittäiseksi scrumiksi.","also":["standup","stand-upit","päivittäiskokous","päivittäinen scrum","daily scrum","daily stand-up","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Työtapa, jossa kortit siirtyvät taulun sarakkeiden läpi (kuten Tehtävänä, Työn alla, Valmis) ja tiimi rajoittaa, kuinka paljon on työn alla kerralla, jotta työ pysyy liikkeessä."},{"id":"wip","g":"agile","word":"WIP-raja","text":"WIP on lyhenne sanoista work in progress, eli työn alla oleva työ. WIP-raja on suurin määrä kortteja, jonka sarake saa sisältää kerralla, jotta tiimi saa asioita valmiiksi ennen kuin aloittaa lisää.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Tiimin lyhyt tarkistuslista siitä, mitä ”valmis” tarkoittaa, esimerkiksi testattu ja selitetty, ennen kuin kortti annetaan sinulle. Sen kaksonen, Definition of Ready, kertoo, milloin kortti on tarpeeksi selkeä aloitettavaksi.","also":["Definition of Ready","valmiin määritelmä","Definition of Done","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Säännöllinen katsaus siihen, miten tiimi työskentelee, jotta sovitaan yhdestä tai kahdesta asiasta, jotka tehdään paremmin ensi kerralla. Lyhenne sanasta retrospektiivi. AI-gilessä retro ehdottaa muutosta tiimin toimintatapoihin, ja sinä sanot Go tai Ei vielä.","also":["retrot","retrospektiivi","retrospektiivit"]},{"id":"swarm","g":"agile","word":"Parvi","text":"Kaikki apuun: moni jättää muun työn ja korjaa yhdessä yhtä kiireellistä asiaa, kunnes se on hoidettu. AI-gilessä kaikki tiimit auttavat yhdessä projektissa, ja muut projektit odottavat sillä välin.","also":["parveilu","parveilla","swarm"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Scrumissa henkilö, joka auttaa tiimiä työskentelemään hyvin: raivaa esteet tiimin tieltä, pitää palaverit raiteillaan ja valmentaa hyviin tapoihin komentelematta ketään. AI-gilessä Lead Scrum Master huomaa jumittuneet kortit, tuuppaa tiimejä ja muistuttaa sinua siitä, mikä odottaa, kaikissa projekteissa.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Ketterä (Agile)","text":"Tapa tehdä työtä pienin askelin: rakenna vähän, näytä oikeita tuloksia usein, opi ihmisten sanomisesta ja muuta suunnitelmaa matkan varrella sen sijaan, että suunnittelisit kaiken etukäteen.","also":["ketteryys","ketterä kehitys","Agile","Agile development","agile ways of working","ketterän","ketterästi","ketteryyden"]},{"id":"manifesto","g":"agile","word":"Ketterä manifesti","text":"Ohjelmistotekijöiden vuonna 2001 kirjoittama lyhyt julistus. Se asettaa ihmiset, toimivat tulokset, tiiviin yhteistyön asiakkaiden kanssa ja muutoksiin vastaamisen raskaiden suunnitelmien ja paperityön edelle.","also":["ketterän kehityksen manifesti","Agile Manifesto","Manifesto for Agile Software Development","ketterä manifesti","ketterän manifestin"]},{"id":"waterfall","g":"agile","word":"Vesiputousmalli (Waterfall)","text":"Vanhempi työtapa: suunnittele kaikki, rakenna sitten kaikki, testaa sitten kaikki, yksi vaihe kerrallaan. Muutokset myöhään ovat vaikeita ja kalliita.","also":["Waterfall","waterfall model","vesiputousmalli","vesiputousmallin"]},{"id":"iteration","g":"agile","word":"Iteraatio","text":"Yksi kierros, jossa jotain rakennetaan, tarkistetaan ja parannetaan. Ketterä työ on näiden kierrosten ketju, ja sprintti on yksi tällainen kierros.","also":["iteraatiot","iteraation","iteraatiota","iteration","iterations"]},{"id":"increment","g":"agile","word":"Inkrementti","text":"Uusi toimiva pala, joka lisätään tuotteeseen sprintissä tai työkierroksella ja joka sopii yhteen sen kanssa, mitä jo oli.","also":["inkrementit","inkrementin","inkrementtiä","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Suosittu ketterä työtapa: pieni tiimi työskentelee lyhyissä sprinteissä kohti tavoitetta, selkeillä rooleilla ja muutamalla säännöllisellä palaverilla suunnitteluun, tarkistamiseen ja parantamiseen."},{"id":"scrumteam","g":"agile","word":"Scrum-tiimi","text":"Pieni ryhmä, joka tekee työn Scrumissa: tuoteomistaja, Scrum Master ja kehittäjät.","also":["Scrum-tiimit","Scrum team","Scrum teams","Scrum-tiimin"]},{"id":"ceremonies","g":"agile","word":"Scrum-tapahtumat","text":"Scrumin säännölliset palaverit: sprintin suunnittelu, päivittäinen scrum, sprintin katselmointi ja retro. Moni kutsuu niitä seremonioiksi.","also":["seremoniat","Scrum-seremoniat","ceremonies","Scrum ceremonies","Scrum-tapahtumien"]},{"id":"sprintplan","g":"agile","word":"Sprintin suunnittelu","text":"Palaveri sprintin alussa, jossa tiimi sopii, miksi sprintti on tärkeä, mitkä kortit se ottaa työn alle ja miten aloittaa.","also":["suunnittelupalaveri","planning meeting","sprint planning","sprintin suunnittelu","sprintin suunnittelun","suunnittelupalaverin"]},{"id":"sprintgoal","g":"agile","word":"Sprintin tavoite","text":"Yksi lause, joka kertoo, mitä varten sprintti on. Pienet tehtävät voivat muuttua matkan varrella, kunhan tavoite saavutetaan.","also":["sprinttitavoite","sprint goal","sprint goals","sprintin tavoite","sprintin tavoitteen"]},{"id":"sprintbacklog","g":"agile","word":"Sprintin backlog","text":"Käynnissä olevaan sprinttiin valitut kortit sekä tiimin suunnitelma niiden tekemiseksi.","also":["sprint backlog","sprint backlogs","sprinttibacklog","sprintin backlog","sprintin backlogin"]},{"id":"productbacklog","g":"agile","word":"Tuotteen backlog","text":"Täydellinen järjestetty lista kaikesta, mikä tuotteeseen saatetaan rakentaa, tärkein ylimpänä. Se muuttuu koko ajan, kun opit.","also":["product backlog","product backlogs","tuotebacklog","tuotteen backlog","tuotteen backlogin"]},{"id":"productgoal","g":"agile","word":"Tuotetavoite","text":"Suurempi tulos, jota kohti tuote pyrkii ja joka auttaa tiimiä valitsemaan, mitä tehdä seuraavaksi.","also":["tuotteen tavoite","product goal","product goals","tuotetavoitteen","tuotetavoitetta"]},{"id":"refinement","g":"agile","word":"Backlogin jalostus","text":"Backlogin säännöllinen läpikäynti, jossa kortteja siistitään, pilkotaan, järjestetään ja täsmennetään, jotta ne ovat valmiita otettaviksi työn alle. Kutsutaan myös backlog groomingiksi.","also":["backlog refinement","backlog grooming","refinement","grooming","backlogin jalostus"]},{"id":"sprintreview","g":"agile","word":"Sprintin katselmointi","text":"Palaveri sprintin lopussa, jossa tiimi näyttää, mitä sai valmiiksi, ja kuulee, mitä ihmiset ajattelevat, jotta voidaan päättää, mitä seuraavaksi.","also":["sprint review","sprint reviews","sprintin esittely","sprintin katselmointi"]},{"id":"demo","g":"agile","word":"Demo","text":"Valmiin työn näyttäminen toimivana, livenä, niille, jotka sitä pyysivät.","also":["demot","esittely","demos","demon","demoa"],"noTip":1},{"id":"timebox","g":"agile","word":"Aikaraja (timebox)","text":"Kiinteä määrä aikaa johonkin. Kun aika loppuu, lopetat, vaikka kaikki ei olisi valmista.","also":["timebox","timeboxed","timeboxes","aikalaatikko"]},{"id":"velocity","g":"agile","word":"Nopeus (velocity)","text":"Kuinka paljon työtä tiimi yleensä saa valmiiksi sprintissä, ja sen avulla suunnitellaan, kuinka paljon otetaan seuraavalla kerralla. Se ei ole pistemäärä siitä, kuinka kovasti ihmiset tekevät töitä.","also":["velocity","tiimin velocity","team velocity"]},{"id":"capacity","g":"agile","word":"Kapasiteetti","text":"Kuinka paljon työtä tiimi voi ottaa tietyllä jaksolla lomien ja muiden töiden jälkeen.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown-kaavio","text":"Kaavio sprintissä jäljellä olevasta työstä, joka laskee päivä päivältä. Jos viiva pysyy tasaisena, jokin on jumissa.","also":["burndown","burn-down chart","burndown chart","burndown-kaavion"]},{"id":"burnup","g":"agile","word":"Burnup-kaavio","text":"Kaavio valmistuneesta työstä, joka nousee ajan myötä, suunnitellun kokonaismäärän rinnalla, jotta näet, milloin pääset perille.","also":["burnup","burn-up chart","burnup chart","burnup-kaavion"]},{"id":"kanbanboard","g":"agile","word":"Kanban-taulu","text":"Itse taulu: jokaiselle työn vaiheelle oma sarake, ja kortit siirtyvät sarakkeesta toiseen.","also":["Kanban-taulut","Kanban board","Kanban boards","Kanban-taulun","Kanban-taulua"]},{"id":"pullsys","g":"agile","word":"Vetojärjestelmä (pull)","text":"Työtapa, jossa uusi työ alkaa vasta, kun jollakulla on tilaa ottaa se, sen sijaan että sitä kasattaisiin jo valmiiksi täydelle lautaselle.","also":["vetävä malli","pull system","pull-based","pull-järjestelmä","vetojärjestelmä","vetojärjestelmän"]},{"id":"flow","g":"agile","word":"Työn virtaus","text":"Kuinka sujuvasti työ etenee taululla. Hyvä virtaus tarkoittaa, että kortit etenevät eivätkä kasaannu.","also":["virtaus","flow","flow of work","työn virtaus","virtauksen","virtausta"],"noTip":1},{"id":"leadtime","g":"agile","word":"Läpimenoaika","text":"Kuinka kauan kestää siitä, kun joku pyytää jotain, siihen, kun se on valmis.","also":["läpimenoajat","lead time","lead times","läpimenoajan","läpimenoaikaa"]},{"id":"cycletime","g":"agile","word":"Sykliaika","text":"Kuinka kauan kortilla menee siitä, kun työ todella alkaa, siihen, kun se on valmis.","also":["sykliajat","cycle time","cycle times","sykliajan","sykliaikaa"]},{"id":"throughput","g":"agile","word":"Läpimeno (throughput)","text":"Kuinka monta korttia valmistuu viikossa tai missä tahansa tietyssä ajassa.","also":["läpäisykyky","throughput","throughput rate","läpimeno","läpimenon"]},{"id":"bottleneck","g":"agile","word":"Pullonkaula","text":"Yksi vaihe, jossa työ kasaantuu ja hidastaa kaikkea sen takana, kuten pullon kapea kaula.","also":["pullonkaulat","bottleneck","bottlenecks","pullonkaulan","pullonkaulaa"]},{"id":"swimlane","g":"agile","word":"Uimarata (swimlane)","text":"Taulun poikki kulkeva rivi, joka ryhmittelee yhdenlaisia kortteja, kuten kiireellisen työn tai yhden tiimin kortit.","also":["uimaradat","swimlane","swimlanes","swim lane","uimarata","uimaradan","uimarataa"]},{"id":"lean","g":"agile","word":"Lean","text":"Työtapa, joka karsii hukan (kaiken, mikä ei auta asiakasta) ja pitää työn virtaamassa."},{"id":"waste","g":"agile","word":"Hukka","text":"Leanissa kaikki, mikä vaatii vaivaa mutta ei auta asiakasta, kuten odottelu, uudelleentyö tai sellaisen rakentaminen, mitä kukaan ei käytä.","noTip":1},{"id":"kaizen","g":"agile","word":"Jatkuva parantaminen","text":"Vähittäistä paranemista koko ajan pienten säännöllisten muutosten avulla ja sen tarkistamista, että ne auttoivat. Retrot ovat yksi tapa tehdä sitä. Kutsutaan myös kaizeniksi.","also":["kaizen","continuous improvement","jatkuva parantaminen","jatkuvan parantamisen"]},{"id":"selforg","g":"agile","word":"Itseorganisoituva tiimi","text":"Tiimi, joka päättää itse, miten työ tehdään, sen sijaan että sille kerrottaisiin askel kerrallaan.","also":["itseohjautuva tiimi","self-organising","self-organizing team","self-managing team","itseorganisoituva","itseorganisoituvan"]},{"id":"crossfunc","g":"agile","word":"Monialainen tiimi","text":"Tiimi, jolla on kaikki tarvittava osaaminen työn valmiiksi saamiseen itse, kuten suunnittelu, rakentaminen ja testaus.","also":["cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Spike","text":"Lyhyt, aikarajattu selvitys, jolla vastataan kysymykseen ennen sitoutumista varsinaiseen työhön.","also":["spiket","spikes","selvitystehtävä","spiken","spikeä"]},{"id":"rework","g":"agile","word":"Uudelleentyö","text":"Työn tekeminen uudestaan, koska se ei onnistunut ensimmäisellä kerralla.","also":["uudelleentyöstö","rework","reworked","uudelleentyön","uudelleentyötä"]},{"id":"safe","g":"agile","word":"Skaalattu ketteryys (SAFe)","text":"Tapoja käyttää ketteryyttä monessa tiimissä isossa organisaatiossa. SAFe (Scaled Agile Framework) on yksi tunnettu esimerkki.","also":["scaled Agile","skaalattu Agile","skaalattu ketteryys"]},{"id":"repo","g":"build","word":"Repo","text":"Projektin koodikansio koko commit-historiansa kanssa. Se voi olla koneellasi, GitHubissa tai molemmissa.","also":["repositorio","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Koodin erillinen työhaara, jotta muutoksia voi tehdä koskematta päälinjaan.","also":["branchit","haara","haaran","haarat","branches"]},{"id":"commit","g":"build","word":"Commit","text":"Koodin tallennettu tilannekuva lyhyellä merkinnällä siitä, mikä muuttui. Voit aina palata johonkin niistä.","also":["commitit","commitia","commitin","commits"]},{"id":"push","g":"build","word":"Push","text":"Tallennettujen tilannekuviesi (commitien) lähettäminen tältä koneelta jaettuun kopioon verkossa, kuten GitHubiin, jotta ne ovat tallessa varmuuskopiona ja muut saavat ne käyttöönsä."},{"id":"merge","g":"build","word":"Merge","text":"Yhden haaran muutosten yhdistäminen toiseen, yleensä takaisin päälinjaan."},{"id":"pr","g":"build","word":"Pull request","text":"Pyyntö, että haaran muutokset tarkistetaan ja yhdistetään päälinjaan. Jotkin sivustot kutsuvat sitä merge requestiksi.","also":["PR","PR:t","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refaktorointi","text":"Koodin siistiminen muuttamatta sen toimintaa: pienempiä tiedostoja, selkeämpiä nimiä, vähemmän toistoa."},{"id":"bug","g":"build","word":"Bugi","text":"Jokin, mikä ei toimi niin kuin pitäisi.","also":["bugit","bugia","bugin","bug","bugs"]},{"id":"peerreview","g":"build","word":"Vertaisarviointi","text":"Toinen silmäpari: joku muu kuin tekijä tarkistaa työn ennen kuin se tulee sinulle, jotta vähemmän virheitä pääsee läpi. AI-gilessä toinen tekoäly tarkistaa jokaisen kortin.","also":["koodikatselmointi","code review","peer review"]},{"id":"code","g":"build","word":"Koodi","text":"Kirjoitetut ohjeet, jotka kertovat tietokoneelle, mitä sen pitää tehdä. Kutsutaan myös lähdekoodiksi.","also":["lähdekoodi","ohjelmakoodi","source code","code","koodi","koodin","koodia"],"noTip":1},{"id":"proglang","g":"build","word":"Ohjelmointikieli","text":"Kieli koodin kirjoittamiseen, esimerkiksi JavaScript, Python tai Java. Eri kielet sopivat eri töihin.","also":["ohjelmointikielet","programming language","programming languages","ohjelmointikielen","ohjelmointikieltä"]},{"id":"developer","g":"build","word":"Kehittäjä (dev)","text":"Joku, joka kirjoittaa ja muuttaa koodia. Kutsutaan myös ohjelmoijaksi tai ohjelmistokehittäjäksi.","also":["kehittäjät","ohjelmoija","ohjelmoijat","ohjelmistokehittäjä","developer","developers","programmer","programmers","software engineer","kehittäjän","kehittäjää"]},{"id":"software","g":"build","word":"Ohjelmisto","text":"Tietokoneilla ja puhelimilla toimivat ohjelmat, toisin kuin itse laitteet (laitteisto).","noTip":1},{"id":"app","g":"build","word":"Sovellus","text":"Lyhenne englannin sanasta application: ohjelma, jolla ihmiset saavat jotain tehtyä puhelimella, tietokoneella tai verkkoselaimessa.","also":["sovellukset","appi","appit","app","apps","application","applications","sovelluksen","sovellusta"],"noTip":1},{"id":"webapp","g":"build","word":"Verkkosovellus","text":"Sovellus, joka toimii verkkoselaimessa, joten mitään ei tarvitse asentaa.","also":["verkkosovellukset","web-sovellus","web app","web apps","web application","verkkosovelluksen","verkkosovellusta"]},{"id":"frontend","g":"build","word":"Käyttöliittymäpuoli (frontend)","text":"Sovelluksen osa, jonka näet ja jota napsautat: näkymät, painikkeet ja sanat, usein selaimessasi.","also":["frontend","front end","front-end","käyttöliittymäpuoli"]},{"id":"backend","g":"build","word":"Taustajärjestelmä (backend)","text":"Sovelluksen kulissien takana toimiva osa, joka säilyttää tiedot ja tekee työn, kun napsautat jotain, esimerkiksi tarkistaa salasanasi.","also":["backend","back end","back-end","taustapuoli","taustajärjestelmä","taustajärjestelmän"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Työskentelyä sekä käyttöliittymäpuolella että taustajärjestelmässä.","also":["fullstack","full-stack"]},{"id":"ui","g":"build","word":"Käyttöliittymä (UI)","text":"Se, mitä ihminen näkee ja käyttää ruudulla: asettelu, painikkeet, valikot ja teksti.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"Käyttökokemus (UX)","text":"Miltä jonkin käyttäminen tuntuu: helpolta, selkeältä ja miellyttävältä, vai sekavalta ja hitaalta.","also":["UX","user experience","käyttökokemus","käyttökokemuksen","käyttökokemusta"]},{"id":"accessibility","g":"build","word":"Saavutettavuus (a11y)","text":"Asioiden tekeminen kaikkien käytettäviksi, myös niille, jotka eivät näe hyvin, eivät voi käyttää hiirtä tai käyttävät ruudunlukijaa.","also":["a11y","esteettömyys","accessibility","saavutettavuuden","saavutettavuutta"]},{"id":"responsive","g":"build","word":"Responsiivinen suunnittelu","text":"Sivujen tekeminen sellaisiksi, että ne sopivat ja toimivat hyvin kaikilla näyttökooilla, puhelimesta isoon näyttöön.","also":["responsiivinen","responsive design","responsiivisen","responsiivisuus"]},{"id":"designsys","g":"build","word":"Suunnittelujärjestelmä","text":"Yhteinen kokoelma värejä, fontteja, painikkeita ja sääntöjä, jotta jokainen näkymä näyttää ja toimii samalla tavalla.","also":["suunnittelujärjestelmät","design system","design systems","suunnittelujärjestelmän"]},{"id":"architecture","g":"build","word":"Arkkitehtuuri","text":"Järjestelmän yleinen rakenne: mitkä ovat sen pääosat ja miten ne viestivät keskenään."},{"id":"database","g":"build","word":"Tietokanta (DB)","text":"Järjestetty tietovarasto, kuin hyvin tehokas taulukko, jota sovellus voi lukea ja muuttaa.","also":["tietokanta","tietokannat","database","databases","DB","tietokannan","tietokantaa"]},{"id":"schema","g":"build","word":"Tietokantakaavio (skeema)","text":"Tietokannan rakenne: mitä tietotaulukoita siinä on ja mitä kuhunkin kuuluu.","also":["skeema","skeeman","tietokantakaavio","tietokantakaavion","schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Lyhenne sanoista structured query language: kieli, jolla useimmista tietokannoista haetaan tietoja tai muutetaan niitä.","also":["Structured Query Language","kyselykieli"]},{"id":"data","g":"build","word":"Data","text":"Tietokoneen säilyttämä tieto, kuten nimet, tilaukset tai asetukset.","also":["tieto","tiedot","aineisto","dataset","datasets","dataa","datan"],"noTip":1},{"id":"server","g":"build","word":"Palvelin","text":"Koko ajan päällä oleva tietokone, joka vastaa muiden tietokoneiden pyyntöihin, esimerkiksi lähettää verkkosivun, kun käyt siellä.","also":["palvelimet","server","servers","palvelimen","palvelinta"]},{"id":"client","g":"build","word":"Asiakasohjelma (client)","text":"Osapuoli, joka pyytää jotain palvelimelta, yleensä selaimesi tai sovelluksesi. Liike-elämässä sana tarkoittaa myös yksinkertaisesti asiakasta.","also":["client","clients","asiakas","päätelaite","asiakasohjelma","asiakasohjelman"],"noTip":1},{"id":"api","g":"build","word":"API (rajapinta)","text":"Lyhenne sanoista application programming interface (ohjelmointirajapinta): valmis valikoima pyyntöjä, joita yksi ohjelma voi tehdä toiselle, esimerkiksi kun säätiedotuspalvelulta kysytään tämän päivän ennuste.","also":["API","API:t","rajapinta","APIs","application programming interface","rajapinnan","rajapintaa","rajapinnat"]},{"id":"endpoint","g":"build","word":"Päätepiste (endpoint)","text":"Yksi rajapinnan valikon kohta: verkko-osoite, jota ohjelma voi kutsua saadakseen tai lähettääkseen jotain.","also":["päätepisteet","endpoint","endpoints","päätepisteen","päätepistettä"]},{"id":"integration","g":"build","word":"Integraatio","text":"Kahden järjestelmän yhdistäminen niin, että ne toimivat yhdessä, esimerkiksi verkkokauppasi lähettää tilaukset kirjanpito-ohjelmaan.","also":["integraatiot","integrointi","integration","integrations","integraation","integraatiota"]},{"id":"webhook","g":"build","word":"Webhook","text":"Viesti, jonka yksi järjestelmä lähettää toiselle automaattisesti heti, kun jotain tapahtuu, esimerkiksi ”maksu vastaanotettu”.","also":["webhookit","webhooks","webhookin","webhookia"]},{"id":"library","g":"build","word":"Kirjasto","text":"Jonkun toisen kirjoittama valmis koodi, jota voit käyttää uudelleen sen sijaan, että kirjoittaisit sen itse.","also":["kirjastot","koodikirjasto","library","libraries","kirjaston","kirjastoa"],"noTip":1},{"id":"framework","g":"build","word":"Sovelluskehys","text":"Valmis rakenne sovelluksen tekemiseen, joka määrää paljon siitä, miten koodi jäsennellään, kuin talon runko, jonka täytät.","also":["sovelluskehykset","framework","frameworks","sovelluskehyksen","sovelluskehystä"]},{"id":"sdk","g":"build","word":"Kehityspaketti (SDK)","text":"Pakkaus työkaluja, koodia ja esimerkkejä ohjelmiston tekemiseen yhdelle alustalle tai palvelulle.","also":["SDK","SDK:t","software development kit","SDKs"]},{"id":"softdep","g":"build","word":"Ohjelmistoriippuvuus","text":"Kirjasto tai työkalu, jota koodisi tarvitsee toimiakseen. Niiden pitäminen ajan tasalla on tärkeää turvallisuuden kannalta.","also":["ohjelmistoriippuvuudet","software dependency","software dependencies","ohjelmistoriippuvuuden"]},{"id":"package","g":"build","word":"Paketti","text":"Valmiin koodin kokonaisuus, jonka voit asentaa ja ottaa käyttöön projektissa.","also":["paketit","package","packages","paketin","pakettia"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Paketinhallinta","text":"Työkalu, joka hakee ja päivittää paketit, joista koodisi riippuu. npm on yleinen.","also":["paketinhallintaohjelma","package manager","package managers","npm","paketinhallinnan"]},{"id":"git","g":"build","word":"Git","text":"Eniten käytetty työkalu koodimuutosten historian säilyttämiseen, commiteina ja haaroina."},{"id":"github","g":"build","word":"GitHub","text":"Verkkosivusto, joka pitää Git-repot verkossa, jotta tiimit voivat jakaa koodia, tarkistaa muutoksia ja seurata työtä."},{"id":"vcs","g":"build","word":"Versionhallinta","text":"Tiedostojen jokaisen muutoksen täyden historian säilyttäminen, jotta näet, kuka muutti mitä, ja voit palata takaisin tarvittaessa. Git tekee tämän.","also":["lähdekoodin hallinta","version control","source control","version control system","versionhallinnan","versionhallintaa"]},{"id":"clone","g":"build","word":"Kloonaus","text":"Oman täyden kopion tekeminen repositoriosta historioineen omalle koneellesi.","also":["kloonata","kloonattu","klooni","clone","cloned","cloning","kloonauksen"]},{"id":"pull","g":"build","word":"Pull","text":"Uusimpien commitien hakeminen jaetusta kopiosta (kuten GitHubista) omalle koneellesi. Pushin vastakohta.","also":["git pull","pullata"],"noTip":1},{"id":"mainbranch","g":"build","word":"Päähaara (main branch)","text":"Koodin virallinen versio, jonka pohjalta kaikki työskentelevät, usein nimeltään main tai master.","also":["main branch","master branch","päähaara","päähaaran"]},{"id":"conflict","g":"build","word":"Yhdistämisristiriita (merge conflict)","text":"Kun kaksi muutosta koskee samoja rivejä eri tavoin, joten tietokone ei voi yhdistää niitä ja ihmisen täytyy valita.","also":["yhdistämisristiriita","yhdistämisristiriidat","yhdistämisristiriidan","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"Näkymä, joka näyttää tarkasti, mikä kahden version välillä muuttui: lisätyt rivit ja poistetut rivit.","also":["diffit","diffin","diffiä","diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Oma kopiosi jonkun toisen repositoriosta, jota voit muuttaa vaikuttamatta hänen omaansa.","also":["forkit","forkata","forks","forked","forkin"]},{"id":"script","g":"build","word":"Skripti","text":"Lyhyt ohjelma, joka hoitaa yhden tehtävän automaattisesti, kuten siivoaa tiedostoja tai käynnistää sovelluksen.","also":["skriptit","script","scripts","skriptin","skriptiä"],"noTip":1},{"id":"build","g":"build","word":"Koonti (build)","text":"Koodin muuttaminen käyttövalmiiksi tai itse käyttövalmis tulos.","also":["build","builds","koonti","kääntäminen","koonnin","koontia"],"noTip":1},{"id":"compile","g":"build","word":"Kääntäminen (compile)","text":"Ihmisten kirjoittaman koodin muuntaminen muotoon, jota tietokone voi ajaa suoraan.","also":["compile","compiler"]},{"id":"cli","g":"build","word":"Komentorivi (CLI)","text":"Tekstiruutu, jossa kirjoitat tietokoneelle ohjeita napsauttelun sijaan. Kutsutaan myös terminaaliksi.","also":["komentorivi","terminaali","command line","command-line","CLI","terminal","komentorivin","komentorivillä","terminaalin"]},{"id":"config","g":"build","word":"Konfiguraatio (config)","text":"Asetukset, jotka ohjaavat ohjelmiston toimintaa ja jotka pidetään erillään koodista, jotta niitä on helppo muuttaa.","also":["config","konfiguraatio","configuration","asetukset","konfiguraation"],"noTip":1},{"id":"envvar","g":"build","word":"Ympäristömuuttuja","text":"Asetus, joka annetaan ohjelmalle sen käynnistyessä, usein osoitteille tai salasanoille, jotta niitä ei kirjoiteta koodiin.","also":["ympäristömuuttujat","environment variable","environment variables","env var","ympäristömuuttujan","ympäristömuuttujaa"]},{"id":"debugging","g":"build","word":"Virheenjäljitys (debugging)","text":"Sen selvittäminen, miksi jokin ei toimi, ja sen korjaaminen.","also":["virheenkorjaus","debugging","debug","debugged","debugata","virheenjäljitys","virheenjäljityksen"]},{"id":"pairing","g":"build","word":"Pariohjelmointi","text":"Kaksi ihmistä (tai ihminen ja tekoäly) työskentelee yhdessä samalla koodilla, toinen kirjoittaa ja toinen tarkistaa.","also":["pariohjelmoinnin","pariohjelmointia","pair programming","pairing"]},{"id":"docs","g":"build","word":"Dokumentaatio (docs)","text":"Kirjalliset selitykset siitä, miten jokin toimii tai miten sitä käytetään.","also":["dokumentaatio","ohjeet","docs","documentation","dokumentaation","dokumentaatiota"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Ensimmäinen luettava tiedosto repositoriossa: mikä projekti on ja miten sen saa käyntiin.","also":["READMEt","lueminut"]},{"id":"legacy","g":"build","word":"Perintöjärjestelmä (legacy)","text":"Vanhempi järjestelmä, joka on yhä käytössä ja jota on vaikea muuttaa, usein koska harva enää ymmärtää sitä.","also":["legacy","legacy system","legacy systems","legacy code","perintöjärjestelmä","perintöjärjestelmän"]},{"id":"techdebt","g":"build","word":"Tekninen velka","text":"Oikopolut, jotka säästävät aikaa nyt mutta hidastavat myöhempiä muutoksia, kuin laina, jolle kertyy korkoa. Refaktorointi maksaa sitä pois.","also":["tech debt","technical debt","tekninen velka","teknisen velan","teknistä velkaa"]},{"id":"test","g":"test","word":"Testi","text":"Tarkistus siitä, että jokin toimii niin kuin pitää. Joitakin testejä tietokone ajaa automaattisesti aina, kun koodi muuttuu; toiset ovat sitä, että kokeilet valmista korttia ennen kuin hyväksyt sen.","also":["testit","testata","testaus","testaat","testaa","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Lyhenne sanoista quality assurance, laadunvarmistus: kaikki, mitä tehdään sen varmistamiseksi, että työ on oikein ennen julkaisua. AI-gilessä se tarkoittaa automaattisia tarkistuksia: kun QA on punainen, jokin epäonnistui, eikä sitä voi julkaista, ennen kuin se on korjattu.","also":["laadunvarmistus","laaduntarkistus","laaduntarkistukset"]},{"id":"testpile","g":"test","word":"Testipino","text":"Valmiit kortit, jotka odottavat, että kokeilet niitä, yksi kerrallaan. Hyväksy kortti tai lähetä se takaisin viestin kanssa, niin seuraava tulee esiin.","also":["testipinot","testipinossa"]},{"id":"autotest","g":"test","word":"Automaattinen testi","text":"Tarkistus, jonka tietokone ajaa automaattisesti aina, kun koodi muuttuu, jotta virheet huomataan ajoissa.","also":["automaattiset testit","automatisoitu testi","automated test","automated tests","automatic tests","automaattisen testin","automaattisia testejä"]},{"id":"manualtest","g":"test","word":"Manuaalinen testi","text":"Ihminen kokeilee työtä käsin nähdäkseen, toimiiko se niin kuin pitää.","also":["manuaaliset testit","manuaalitestaus","käsin testaus","manual test","manual tests","manual testing","manuaalisen testin"]},{"id":"unittest","g":"test","word":"Yksikkötesti","text":"Pieni automaattinen tarkistus yhdelle pienelle koodinpalalle erikseen.","also":["yksikkötestit","unit test","unit tests","yksikkötestin","yksikkötestejä"]},{"id":"integtest","g":"test","word":"Integraatiotesti","text":"Tarkistus siitä, että useat osat toimivat kunnolla yhdessä, eivät vain yksi kerrallaan.","also":["integraatiotestit","integration test","integration tests","integraatiotestin"]},{"id":"endtoend","g":"test","word":"Päästä päähän -testi (E2E)","text":"Testi, joka toimii kuin oikea käyttäjä alusta loppuun, esimerkiksi rekisteröityy, ostaa ja maksaa.","also":["E2E","päästä päähän","end-to-end tests","päästä päähän -testi","päästä päähän -testit"]},{"id":"uat","g":"test","word":"Hyväksymistestaus (UAT)","text":"Työn tilanneet kokeilevat sitä itse ja kertovat, tekeekö se sen, mitä he tarvitsevat. AI-gilen testipino on juuri tätä.","also":["UAT","acceptance testing","käyttäjän hyväksymistestaus","hyväksymistestaus","hyväksymistestauksen"]},{"id":"regression","g":"test","word":"Regressio","text":"Jokin, mikä ennen toimi, mutta meni rikki muutoksen jälkeen. Regressiotestit tarkistavat, että vanhat asiat yhä toimivat.","also":["regressiot","regressiotesti","regressiotestit","regressiotestaus","regression","regressions","regression test","regression tests","regression testing","regressiota"]},{"id":"smoke","g":"test","word":"Savutesti (smoke test)","text":"Hyvin nopea tarkistus siitä, että tärkeimmät asiat toimivat ylipäätään, esimerkiksi heti muutoksen julkaisun jälkeen. Jos se epäonnistuu, pysähdy ja tutki.","also":["savutesti","smoke test","smoke tests","savutestin","savutestit"]},{"id":"exploratory","g":"test","word":"Tutkiva testaus","text":"Tuotteen vapaa kokeilu ja sen tökkiminen eri tavoin, jotta löytyy ongelmia, jotka suunnitellut tarkistukset jättäisivät huomaamatta.","also":["tutkiva testi","exploratory testing","exploratory test","exploratory tests","tutkiva testaus","tutkivan testauksen"]},{"id":"testcase","g":"test","word":"Testitapaus","text":"Yksi kirjoitettu kokeiltava tilanne: vaiheet ja se, mitä pitäisi tapahtua.","also":["testitapaukset","test case","test cases","testitapauksen"]},{"id":"coverage","g":"test","word":"Testikattavuus","text":"Kuinka suuren osan koodista automaattiset testit tarkistavat. Enemmän on yleensä turvallisempaa, mutta pelkkä korkea kattavuus ei todista, että kaikki toimii hyvin.","also":["koodikattavuus","test coverage","code coverage","testikattavuuden"]},{"id":"testdata","g":"test","word":"Testidata","text":"Keksittyjä esimerkkitietoja, joita käytetään testauksessa, jotta kenenkään oikean ihmisen yksityisiä tietoja ei paljasteta.","also":["testitiedot","test data","test fixtures","testidatan","testidataa"]},{"id":"edgecase","g":"test","word":"Reunatapaus (edge case)","text":"Epätavallinen tilanne äärirajoilla, kuten tyhjä lomake tai heittomerkkiä sisältävä nimi, jossa asiat menevät usein rikki.","also":["reunatapaukset","edge case","edge cases","reunatapauksen","reunatapauksia"]},{"id":"happypath","g":"test","word":"Onnellinen polku (happy path)","text":"Tavallinen reitti, jossa kaikki menee oikein. Hyvä testaus kokeilee myös polkuja, joilla jokin menee vikaan."},{"id":"perftest","g":"test","word":"Suorituskykytestaus","text":"Sen tarkistaminen, kuinka nopea jokin on ja kuinka hyvin se kestää kuormitusta.","also":["suorituskykytesti","suorituskykytestit","performance testing","performance test","performance tests","suorituskykytestauksen"]},{"id":"loadtest","g":"test","word":"Kuormitustestaus","text":"Sen tarkistaminen, miten järjestelmä pärjää, kun moni käyttää sitä yhtä aikaa.","also":["kuormitustesti","kuormitustestit","load testing","load test","load tests","kuormitustestauksen"]},{"id":"sectest","g":"test","word":"Tietoturvatestaus","text":"Heikkouksien etsimistä, joiden kautta joku voisi käyttää järjestelmää väärin tai nähdä sen, mitä ei saisi.","also":["tietoturvatesti","tietoturvatestit","security testing","security test","security tests","tietoturvatestauksen"]},{"id":"accesstest","g":"test","word":"Saavutettavuustestaus","text":"Sen tarkistaminen, että eri tavoin toimivat ihmiset voivat käyttää tuotetta, myös ruudunlukijalla tai pelkällä näppäimistöllä.","also":["saavutettavuustesti","esteettömyystestaus","accessibility testing","accessibility test","saavutettavuustestauksen"]},{"id":"linting","g":"test","word":"Linttaus","text":"Automaattinen tarkistus, joka huomaa todennäköisiä virheitä ja sotkuista tyyliä koodissa, kuin ohjelmien oikoluku.","also":["linter","lint","linttaus","linttauksen"]},{"id":"static","g":"test","word":"Staattinen analyysi","text":"Koodin tarkistaminen ongelmien varalta lukemalla sitä automaattisesti ajamatta sitä.","also":["staattinen koodianalyysi","static analysis","static code analysis","staattisen analyysin"]},{"id":"flaky","g":"test","word":"Epävakaa testi (flaky)","text":"Testi, joka joskus menee läpi ja joskus ei ilman selvää syytä, joten siihen ei voi täysin luottaa.","also":["epävakaat testit","flaky test","flaky tests","flaky","epävakaa testi"]},{"id":"repro","g":"test","word":"Toistaminen (repro)","text":"Virheen saaminen tapahtumaan uudelleen tarkoituksella seuraamalla samoja vaiheita, jotta sitä voi tutkia ja korjata. Näiden vaiheiden kirjoittaminen on virheraportin hyödyllisin osa.","also":["repro","reproduce","steps to reproduce","toistamisvaiheet"]},{"id":"severity","g":"test","word":"Vakavuus","text":"Kuinka paha ongelman vaikutus on, pienestä ärsytyksestä siihen, että kaikki pysähtyy.","also":["vakavuusaste","severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Ohjelmiston uuden version kopioiminen sitä ajaville koneille, kuten testikopioon tai tuotantopalveluun."},{"id":"release","g":"change","word":"Julkaisu","text":"Nimetty nippu valmista työtä, joka julkaistaan yhdessä, ja lyhyet muistiinpanot siitä, mikä muuttui. 🚀 Julkaisut kirjoittaa muistiinpanot valmiista korteista.","also":["julkaisut","julkaisun","julkaisua","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Paluu viimeiseen toimineeseen versioon, kun uusi aiheuttaa ongelmia. AI-gilessä Rollback kokoaa jokaiseen muutokseen kirjoitetut kumoamisvaiheet yhdeksi tarkistuslistaksi.","also":["rollbackin","peruutus","peruuttaa","palata edelliseen versioon"]},{"id":"live","g":"change","word":"Tuotanto","text":"Oikea versio, jota ihmiset käyttävät, eikä kopio asioiden kokeilemiseen. Englanniksi sitä kutsutaan myös nimellä live.","also":["tuotannossa","tuotantoon","live"],"noTip":1},{"id":"change","g":"change","word":"Muutos","text":"Suunniteltu muutos johonkin, johon ihmiset luottavat, kirjattuna etukäteen: mitä, miksi, riski, milloin ja miten sen saa peruttua. Aloita sellainen napista 🔀 Tee muutospyyntö.","also":["muutokset","muutosta","muutospyyntö","muutospyynnöt"],"noTip":1},{"id":"risk","g":"change","word":"Riski","text":"Jokin, mikä voi mennä pieleen, pisteytettynä sen mukaan, kuinka todennäköistä ja kuinka pahaa se olisi. ⚠️ Riskit pitää ne yhdellä listalla, korkeimmat pisteet ensin, ja jokaisella on päivä, jolloin se katsotaan uudelleen.","also":["riskit","riskiä","riskirekisteri"]},{"id":"chgwin","g":"change","word":"Muutosikkuna","text":"Ajat, jolloin muutoksia saa julkaista, esimerkiksi rauhallinen tiistai-ilta. Ikkunan ulkopuolella muutoskorttia ei voi merkitä valmiiksi, ellei kyse ole hätätilanteesta.","also":["muutosikkunat","muutosikkunan"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"Viimeinen tarkistus juuri ennen muutoksen julkaisua: jokainen hyväksyjä sanoo Go tai No go. Muutos etenee vain, kun kaikki sanovat Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Hyväksyntä","text":"Kyllä-vastauksen odottamista ennen kuin työ alkaa. Ystävän tekemä kortti tai muutos odottaa kohdassa ✅ Hyväksynnät, kunnes hyväksyt tai hylkäät sen.","also":["hyväksynnät","hyväksyntää"]},{"id":"quiettime","g":"change","word":"Hiljainen aika","text":"Ajanjakso, esimerkiksi suoran lähetyksen, demon tai yön aikana, jolloin mitään ei julkaista. Tiimit jatkavat työtä ja testausta, mutta julkaisu odottaa, kunnes se päättyy. Muualla sitä kutsutaan muutosjäädytykseksi.","also":["hiljaiset ajat","muutosjäädytys","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Työtapa, jossa ohjelmiston tekijät ja sen ylläpitäjät toimivat yhtenä tiiminä ja automatisoivat paljon, jotta muutokset menevät tuotantoon usein ja turvallisesti."},{"id":"cicd","g":"change","word":"CI/CD (jatkuva integrointi ja toimitus)","text":"Kaikkien muutokset yhdistetään usein päälinjaan ja tarkistetaan automaattisesti joka kerta (jatkuva integrointi), jotta ohjelmisto on aina valmis julkaistavaksi napin painalluksella (jatkuva toimitus).","also":["CI/CD","CD","jatkuva integrointi","jatkuva toimitus","continuous integration","continuous delivery","jatkuvan integroinnin"]},{"id":"contdeploy","g":"change","word":"Jatkuva käyttöönotto","text":"Yksi askel pidemmälle kuin jatkuva toimitus: jokainen tarkistukset läpäisevä muutos menee tuotantoon automaattisesti, ilman painettavaa nappia.","also":["jatkuva julkaisu","continuous deployment","continuous deployments","jatkuva käyttöönotto","jatkuvan käyttöönoton"]},{"id":"pipeline","g":"change","word":"Putki (pipeline)","text":"Automaattinen vaiheiden sarja, jonka muutos käy läpi matkalla tuotantoon, esimerkiksi koonti, testaus ja sitten käyttöönotto.","also":["pipeline","pipelines"]},{"id":"environment","g":"change","word":"Ympäristö","text":"Yksi erillinen kopio järjestelmästä yhtä tarkoitusta varten, esimerkiksi yksi rakentamiseen, yksi testaamiseen ja tuotantoympäristö.","also":["ympäristöt","environment","environments","ympäristön","ympäristössä"],"noTip":1},{"id":"devenv","g":"change","word":"Kehitysympäristö","text":"Kopio, jossa kehittäjä työskentelee, usein omalla koneellaan, ja jossa asioiden rikkominen ei vahingoita ketään.","also":["dev-ympäristö","development environment","dev environment","kehitysympäristön","kehitysympäristössä"]},{"id":"testenv","g":"change","word":"Testiympäristö","text":"Erillinen kopio järjestelmästä pelkkää testausta varten, jotta oikeaan palveluun ei kosketa.","also":["testiympäristöt","test environment","test environments","testiympäristön","testiympäristössä"]},{"id":"staging","g":"change","word":"Staging","text":"Viimeinen kopio, joka on pystytetty täsmälleen tuotannon kaltaiseksi, lopputarkistusta varten ennen kuin muutos julkaistaan.","also":["staging-ympäristö","esituotanto","staging environment","stagingissa","esituotannossa"]},{"id":"artifact","g":"change","word":"Koontiartefakti","text":"Tiedosto tai paketti, jonka koonti tuottaa, valmiina tallennettavaksi, tarkistettavaksi tai julkaistavaksi.","also":["koontiartefaktit","build artifact","build artifacts","koontiartefaktin"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Kiireellinen korjaus, joka viedään nopeasti tuotantoon tavallisen suunnitelman ulkopuolella, koska jokin tärkeä on rikki.","also":["hotfixit","pikakorjaus","hotfixes","hotfixin","pikakorjauksen"]},{"id":"patch","g":"change","word":"Korjauspäivitys (patch)","text":"Pieni päivitys, joka korjaa virheen tai sulkee tietoturva-aukon. Tietoturvapäivitysten nopea asentaminen on tärkeää.","also":["patch","patches","tietoturvapäivitys","tietoturvapäivitykset","security patch","security patches","korjauspäivitys","korjauspäivityksen"]},{"id":"version","g":"change","word":"Versionumero","text":"Merkintä, kuten 2.4.1, joka kertoo, mikä julkaisu sinulla on. Usein ensimmäinen numero muuttuu isoissa muutoksissa ja viimeinen pienissä korjauksissa.","also":["versionumerot","semanttinen versiointi","version number","version numbers","semantic versioning","versionumeron"]},{"id":"relnotes","g":"change","word":"Julkaisutiedot","text":"Lyhyt selkeä luettelo siitä, mikä julkaisussa muuttui, sen käyttäjille, mukana korjaukset ja tunnetut rajoitukset. Kutsutaan myös muutoslokiksi.","also":["muutoshistoria","muutosloki","changelog","change log","release notes","julkaisutiedot","julkaisutietojen"]},{"id":"flag","g":"change","word":"Ominaisuuskytkin (feature flag)","text":"Päälle- ja poiskytkin ominaisuudelle, jotta uusi työ voidaan viedä tuotantoon piilotettuna ja kytkeä päälle (tai taas pois) ilman uutta julkaisua.","also":["feature flag","feature flags","feature toggle","feature toggles","ominaisuuslippu","ominaisuuskytkin","ominaisuuskytkimen"]},{"id":"rollfwd","g":"change","word":"Korjaus eteenpäin (roll forward)","text":"Huonon julkaisun korjaaminen viemällä nopeasti ulos uusi, korjattu versio sen sijaan, että palattaisiin vanhaan.","also":["roll forward","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Kanarianlintu-julkaisu (canary)","text":"Muutoksen vieminen ensin pienelle ryhmälle ja kaikille vasta, kun se näyttää hyvältä. Nimi tulee kanarianlinnuista, jotka kaivostyöläiset veivät maan alle varhaiseksi varoitukseksi.","also":["canary","canary release","canary releases","kanarianlintu","kanarianlintu-julkaisu"]},{"id":"bluegreen","g":"change","word":"Sinivihreä käyttöönotto","text":"Tuotantojärjestelmästä pidetään kaksi kopiota ja ihmiset siirretään uuteen yhdellä kertaa, jotta voi vaihtaa heti takaisin, jos jokin menee pieleen.","also":["blue-green","blue-green deployment","blue green deployment","sinivihreä käyttöönotto","sinivihreän käyttöönoton"]},{"id":"zerodown","g":"change","word":"Käyttöönotto ilman käyttökatkoa","text":"Uuden version vieminen tuotantoon niin, ettei palvelu katkea käyttäjiltä hetkeksikään.","also":["zero downtime","zero-downtime","ilman käyttökatkoa"]},{"id":"chgenable","g":"change","word":"Muutoksenhallinta","text":"Muutosten onnistumisen tukeminen: riskin punnitseminen, oikean hyväksynnän hankkiminen ja hyvän ajankohdan valinta. Kutsutaan myös change managementiksi.","also":["muutosten hallinta","change enablement","change management","muutoksenhallinnan","muutostenhallinta"]},{"id":"cab","g":"change","word":"Muutoslautakunta (CAB)","text":"Ryhmä, joka tarkastelee tärkeitä muutoksia ja sopii, saako ne tehdä ja milloin.","also":["CAB","change advisory board","muutosneuvosto","muutoslautakunnan"]},{"id":"stdchange","g":"change","word":"Vakiomuutos","text":"Pienen riskin muutos, joka tehdään joka kerta samalla koeteltulla tavalla, joten se on hyväksytty etukäteen.","also":["vakiomuutokset","standard change","standard changes","vakiomuutoksen"]},{"id":"normchange","g":"change","word":"Normaali muutos","text":"Muutos, joka pitää tarkistaa ja hyväksyttää ennen kuin se tehdään.","also":["normaalit muutokset","normal change","normal changes","normaalin muutoksen"]},{"id":"emergchange","g":"change","word":"Hätämuutos","text":"Muutos, joka on tehtävä heti vakavan ongelman korjaamiseksi tai estämiseksi, ja hyväksyntäkin on sen mukaisesti nopeampi.","also":["hätämuutokset","kiireellinen muutos","emergency change","emergency changes","hätämuutoksen"]},{"id":"automation","g":"change","word":"Automaatio","text":"Toistuvan työn antaminen tietokoneen hoidettavaksi automaattisesti, jotta se käy nopeammin ja tehdään joka kerta samalla tavalla.","also":["automatisointi","automaattinen","automation","automated","automaation"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktuuri","text":"Koneet, verkot ja palvelut, joilla ohjelmisto toimii.","also":["infra","infrastructure","infrastruktuuri","infrastruktuurin"]},{"id":"iac","g":"change","word":"Infrastruktuuri koodina (IaC)","text":"Palvelinten ja asetusten kuvaaminen tiedostoissa, jotka säilytetään koodin kanssa, jotta ne voi rakentaa uudelleen täsmälleen samalla tavalla joka kerta.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Pilvi","text":"Tietokoneiden, tallennustilan ja palvelujen vuokraaminen isolta tarjoajalta internetin kautta sen sijaan, että omistaisi koneet itse.","also":["pilvipalvelu","pilvilaskenta","cloud","the cloud","cloud computing","pilvessä","pilveen","pilven"]},{"id":"provider","g":"change","word":"Pilvipalveluntarjoaja","text":"Yritys, joka vuokraa laskentatehoa internetin kautta, kuten Amazon Web Services (AWS), Microsoft Azure tai Google Cloud.","also":["pilvipalveluntarjoajat","cloud provider","cloud providers","pilvipalveluntarjoajan"]},{"id":"hosting","g":"change","word":"Hosting (palvelintila)","text":"Paikka, jossa sovelluksesi tai verkkosivustosi sijaitsee ja toimii, jotta ihmiset pääsevät siihen, yleensä vuokrattuna yritykseltä.","also":["hosting","palvelintila","palvelintilan","webhotelli","webhotellin"]},{"id":"domain","g":"change","word":"Verkkotunnus","text":"Verkko-osoite, jonka ihmiset kirjoittavat, kuten example.com. Vuokraat sen vuodeksi kerrallaan, joten se pitää uusia.","also":["verkkotunnukset","domain","domain name","domain names","toimialuenimi","verkkotunnuksen","verkkotunnusta"]},{"id":"dns","g":"change","word":"DNS","text":"Lyhenne sanoista domain name system: internetin osoitekirja, joka muuttaa nimen, kuten example.com, oikean tietokoneen osoitteeksi.","also":["domain name system","nimipalvelu"]},{"id":"container","g":"change","word":"Kontti (container)","text":"Suljettu paketti, jossa on sovellus ja kaikki, mitä se tarvitsee, jotta se toimii samalla tavalla millä tahansa tietokoneella. Docker on tunnetuin työkalu.","also":["kontti","kontit","container","containers","Docker","kontin"],"noTip":1},{"id":"vm","g":"change","word":"Virtuaalikone (VM)","text":"Ohjelmalla jäljitelty tietokone, joka pyörii oikean koneen sisällä, jotta yksi iso kone voi toimia monena.","also":["VM","VM:t","virtuaalikoneet","virtual machine","virtual machines","VMs","virtuaalikoneen"]},{"id":"serverless","g":"change","word":"Serverless","text":"Koodin ajaminen ilman, että huolehdit itse yhdestäkään palvelimesta: tarjoaja ajaa sen tarvittaessa ja maksat vain käytöstä."},{"id":"lb","g":"change","word":"Kuormantasaaja","text":"Järjestelmä, joka jakaa kävijät usealle palvelimelle, jotta yksikään ei ylikuormitu.","also":["load balancer","load balancers","kuormantasaus","kuormantasaajan"]},{"id":"cache","g":"change","word":"Välimuisti (cache)","text":"Lähellä pidettävä kätevä varasto viimeaikaisista tuloksista, jotta samaa ei tarvitse hakea tai laskea uudelleen. Sen tyhjentäminen voi korjata sivut, jotka näyttävät vanhentuneilta.","also":["cache","caches","caching","cached","välimuisti","välimuistin","välimuistia"]},{"id":"cdn","g":"change","word":"Sisällönjakeluverkko (CDN)","text":"Maailmanlaajuinen palvelinjoukko, jolla on kopiot sivuistasi ja kuvistasi lähellä kävijöitä, jotta ne latautuvat nopeasti.","also":["CDN","content delivery network","sisällönjakeluverkko"]},{"id":"migration","g":"change","word":"Migraatio","text":"Tietojen tai järjestelmien siirtäminen vanhasta ratkaisusta uuteen tai tietokannan rakenteen huolellinen muuttaminen.","also":["migraatiot","migraation","migraatiota","migration","migrations","database migration","tietokantamigraatio"]},{"id":"service","g":"run","word":"Palvelu","text":"Jotain, minkä rakensit ja mihin ihmiset luottavat, kuten verkkosivu tai sovellus, ja josta pidetään huolta, jotta se toimii jatkossakin. Rastita ”Tämä projekti on palvelu” ja kerro, mitä se tarjoaa, ketkä sitä käyttävät ja kuka päivystää.","also":["palvelut","palvelun","palvelua"]},{"id":"uptimepct","g":"run","word":"Käytettävyysaika (uptime)","text":"Kuinka suuren osan ajasta palvelu toimii, yleensä prosenttina. 99,9 % sallii silti noin 43 minuuttia käyttökatkoa kuukaudessa.","also":["uptime","uptime percentage","käytettävyysprosentti","käytettävyysaika"]},{"id":"uptime","g":"run","word":"Käytettävyystarkistus","text":"Automaattinen tarkistus muutaman minuutin välein, että palvelusi vielä vastaa. Jos se epäonnistuu monta kertaa peräkkäin, AI-gile avaa itse häiriökortin.","also":["käytettävyystarkistukset","uptime checks"]},{"id":"statuspage","g":"run","word":"Tilasivu","text":"Julkinen sivu, joka näyttää, toimiiko palvelu (vihreä, oranssi vai punainen), ja uusimman tiedotteen, jotta käyttäjät voivat katsoa itse kysymisen sijaan.","also":["tilasivut","tilasivulla","status page"]},{"id":"desk","g":"run","word":"Palvelupiste","text":"Paikka, johon palvelusi käyttäjien kysymykset ja ilmoitukset saapuvat. AI-gile lajittelee jokaisen pyynnöksi, häiriöksi tai ideaksi ja kertoo, jos se muistuttaa jotain jo ilmoitettua.","also":["palvelupisteet","pöytä","service desk","helpdesk","tukipalvelu"]},{"id":"svcrequest","g":"run","word":"Palvelupyyntö","text":"Joku pyytää jotain tavallista, kuten uutta tiliä tai vähän apua, sen sijaan että ilmoittaisi jonkin olevan rikki. Se odottaa vuoroaan; häiriö menee edelle.","also":["palvelupyynnöt","palvelupyynnön"]},{"id":"incident","g":"run","word":"Häiriö","text":"Jokin, mikä on rikki tai ei toimi kunnolla niille, jotka käyttävät sitä juuri nyt, esimerkiksi kun verkkosivusto on alhaalla tai hyvin hidas. 🔥 Häiriökortti ohittaa jonon: sen saaminen taas toimimaan menee kaiken edelle.","also":["häiriöt","häiriön","häiriötä","incident"]},{"id":"major","g":"run","word":"Suuri häiriö","text":"Iso häiriö: paljon ihmisiä kärsii, tai rahaa tai tietoja on vaarassa. Yksi nappi laittaa kaikki tiimit asian kimppuun (parvi), herättää päivystäjän ja pyytää tilannepäivityksen 30 minuutin välein.","also":["suuret häiriöt","vakava häiriö","major incident"]},{"id":"oncall","g":"run","word":"Päivystys","text":"Olla se, joka reagoi, kun jokin hajoaa, myös yöllä. Jokaisella palvelulla on päivystävä tiimiläinen, joka herätetään ensimmäisenä sen häiriöissä.","also":["päivystäjä","päivystää","on call","on-call"]},{"id":"replyby","g":"run","word":"Vastausaika","text":"Kuinka kauan kortti saa odottaa ensimmäistä vastausta, esimerkiksi tunnin häiriön kohdalla. Sen jälkeen se saa punaisen kellon, jottei mitään unohdeta hiljaa. Sitä kutsutaan myös vastausaikatavoitteeksi.","also":["vastausajat","vastausaikatavoite","vastausaikatavoitteet"]},{"id":"postmortem","g":"run","word":"Jälkipuinti","text":"Lyhyt katsaus taaksepäin häiriön jälkeen: mitä tapahtui, mikä auttoi ja mitä muutetaan, ketään syyllistämättä. Häiriötä ei voi sulkea ilman sitä.","also":["jälkipuinnit","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Ongelma","text":"Piilossa oleva syy yhden tai useamman häiriön takana. 🧩 Ongelmakortti kokoaa yhteen häiriöt, jotka toistuvat, jotta syy löydetään ja korjataan lopullisesti.","also":["ongelmat","ongelman","ongelmaa"],"noTip":1},{"id":"rootcause","g":"run","word":"Juurisyy","text":"Todellinen syy siihen, miksi jokin hajosi, eikä vain se, minkä näit menevän pieleen. Korjaa juurisyy, niin häiriö lakkaa toistumasta.","also":["juurisyyt","perimmäinen syy"]},{"id":"workaround","g":"run","word":"Väliaikainen ratkaisu","text":"Keino pitää asiat toiminnassa, kunnes oikea korjaus on valmis, kuten jonkin uudelleenkäynnistys, kun se jumittuu. Se kirjataan ongelmakorttiin, jottei kenenkään tarvitse keksiä sitä uudelleen.","also":["väliaikaiset ratkaisut","kiertotie","workaround"]},{"id":"knownerror","g":"run","word":"Tunnettu virhe","text":"Ongelma, jonka syy tiedetään mutta jota ei ole vielä korjattu ja jolle on yleensä kirjattu väliaikainen ratkaisu. 🧩 Tunnetut virheet luettelee ne, jotta kaikki käyttävät väliaikaista ratkaisua eivätkä ala kaivella uudelleen.","also":["tunnetut virheet","tunnetun virheen"]},{"id":"runbook","g":"run","word":"Ohjekirja","text":"Vaiheittaiset ohjeet tunnetun vian korjaamiseen, jotta se tehdään joka kerta samalla tavalla ja nopeasti. Suuren häiriön jälkeen tiimi voi ehdottaa sellaista, ja sinä hyväksyt sen.","also":["ohjekirjat","runbook","runbookit"]},{"id":"ci","g":"run","word":"Kokoonpanokohde","text":"Yksi asia, josta palvelusi riippuu, kuten palvelin, verkkotunnus, varmenne, avain tai toimittaja. 🗂️ Kokoonpanokohteet listaa ne palveluittain, jotta näet, mihin häiriö vaikuttaa ja mitä pitää uusia tai varmuuskopioida.","also":["kokoonpanokohteet","kokoonpanokohteen","CI"]},{"id":"expiry","g":"run","word":"Vanhenemispäivä","text":"Päivämäärä, jona jokin lakkaa toimimasta, ellei sitä uusita, kuten verkkosivuston turvavarmenne tai sen verkko-osoite. AI-gile seuraa näitä päiviä ja tekee kullekin uusimiskortin 30 päivää etukäteen, jotta mikään ei pysähdy yllättäen.","also":["vanhenemispäivät","vanheneminen","vanhenemisen seuranta"]},{"id":"backup","g":"run","word":"Varmuuskopio","text":"Aiemmin tallennettu kopio tiedoistasi, johon voi palata, jos jotain katoaa tai vahingoittuu. AI-gile ottaa tauluistasi varmuuskopion joka päivä.","also":["varmuuskopiot","varmuuskopion","backup"]},{"id":"restore","g":"run","word":"Palautus","text":"Tietojen palauttaminen varmuuskopiosta. Varmuuskopio on oikeasti jonkin arvoinen vasta, kun tiedät, että sen voi palauttaa, joten sitä kannattaa kokeilla silloin tällöin.","also":["palauttaa","palautettu","palauta"]},{"id":"svcreview","g":"run","word":"Palvelukatselmus","text":"Katsaus palvelun yhteen kuukauteen: avatut ja korjatut häiriöt, kuinka nopeasti ihmiset saivat vastauksen, käytettävyys ja käytetyt tokenit. Kuukausikatselmus näyttää sen jokaiselle palvelulle.","also":["palvelukatselmukset","kuukausikatselmus","kuukausikatselmukset"]},{"id":"accessreview","g":"run","word":"Käyttöoikeuskatselmus","text":"Sen tarkistaminen 90 päivän välein, ketkä pääsevät vielä sisään: jakolinkit, ystävien roolit sekä tallennetut salasanat ja avaimet. Päätät kunkin kohdalla, pidätkö vai poistatko sen, jotta vanhat oikeudet eivät jää roikkumaan.","also":["käyttöoikeuskatselmukset"]},{"id":"improvements","g":"run","word":"Parannuslista","text":"Kaikki, missä tiimi päätti parantaa, yhdessä paikassa: retron ehdotukset, katselmuksen toimenpiteet ja ongelmien korjaukset, kukin tilansa kanssa. Löydät sen kohdasta 📈 Parannukset.","also":["parannuslistat","parannukset"]},{"id":"tokencap","g":"run","word":"Tokenraja","text":"Kuukausittainen raja tokeneille, joita palvelun agentit saavat käyttää. 80 %:ssa saat varoituksen; 100 %:ssa niiden taustatyö odottaa seuraavaan kuuhun tai kunnes nostat rajaa.","also":["tokenrajat","kuukausittainen tokenraja"]},{"id":"svcmgmt","g":"run","word":"Palvelunhallinta","text":"Kaikki, mitä tarvitaan pitämään palvelu hyödyllisenä ja toimivana niille, jotka siihen luottavat, päivästä toiseen.","also":["palveluhallinta","service management","palvelunhallinnan"]},{"id":"itil","g":"run","word":"ITIL","text":"Laajasti käytetty opas hyvään palvelunhallintaan, joka kattaa esimerkiksi häiriöt, ongelmat ja muutokset. Nimi oli alun perin lyhenne sanoista IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT-palvelunhallinta (ITSM)","text":"Teknologian pyörittäminen palveluna ihmisille niin, että pyyntöjen, häiriöiden, muutosten ja parannusten käsittelyyn on selkeät tavat.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Hallinnoitu palvelu (managed service)","text":"Palvelu, jota joku muu pyörittää ja hoitaa puolestasi. Sopimuksessa sovitaan, kuinka hyvin sen täytyy toimia.","also":["managed service","managed services","hallittu palvelu"]},{"id":"svcowner","g":"run","word":"Palvelun omistaja","text":"Henkilö, joka vastaa palvelusta kokonaisuutena: kuinka hyvin se toimii, mitä se maksaa ja miten se paranee.","also":["palvelunomistaja","palvelun omistajat","service owner","service owners"]},{"id":"sla","g":"run","word":"Palvelutasosopimus (SLA)","text":"Kirjallinen lupaus asiakkaille siitä, kuinka hyvin palvelu toimii, kuten ”toiminnassa 99,9 % ajasta” tai ”vastaus tunnin sisällä”, ja usein hyvitys, jos lupaus rikotaan.","also":["SLA","SLA:t","service level agreement","SLAs","SLA:n","palvelutasosopimuksen"]},{"id":"slo","g":"run","word":"Palvelutasotavoite (SLO)","text":"Tiimin oma tavoite siitä, kuinka hyvin palvelun pitäisi toimia tietyn jakson aikana, yleensä varmuuden vuoksi hieman SLA:ta tiukempi.","also":["SLO","SLO:t","service level objective","SLOs","SLO:n","palvelutasotavoitteen"]},{"id":"sli","g":"run","word":"Palvelutasomittari (SLI)","text":"Varsinainen mittaus, jota verrataan tavoitteeseen, esimerkiksi niiden käyntien osuus, jotka latautuivat moitteetta.","also":["SLI","SLI:t","service level indicator","SLIs","SLI:n","palvelutasomittarin"]},{"id":"availability","g":"run","word":"Saatavuus","text":"Voivatko ihmiset käyttää palvelua silloin, kun he sitä tarvitsevat, usein mitattuna käytettävyysaikana (uptime).","also":["korkea saatavuus","availability","high availability","saatavuuden"]},{"id":"downtime","g":"run","word":"Käyttökatko","text":"Aika, jolloin palvelu ei toimi tai on kytketty pois, suunniteltu tai ei.","also":["seisokki","downtime","down time","käyttökatkon","käyttökatkoa","käyttökatkot"]},{"id":"errorbudget","g":"run","word":"Virhebudjetti (error budget)","text":"Pieni määrä epäonnistumisia, jonka luotettavuustavoitteesi sallii. Niin kauan kuin sitä on jäljellä, voit ottaa riskejä muutoksissa; kun se on käytetty loppuun, tahtia hidastetaan.","also":["error budget","error budgets","virhebudjetit","virhebudjetin"]},{"id":"outage","g":"run","word":"Palvelukatkos","text":"Aika, jolloin palvelu ei ole käyttäjien käytettävissä tai toimii pahasti väärin.","also":["katkos","outage","outages","palvelukatkos","palvelukatkon","katkoksen"]},{"id":"degraded","g":"run","word":"Heikentynyt toiminta (degraded)","text":"Toimii, mutta huonosti: hitaasti tai osa toiminnoista ei toimi.","also":["degraded","degraded service","heikentynyt palvelu"]},{"id":"monitoring","g":"run","word":"Valvonta","text":"Palvelun automaattinen tarkkailu koko ajan, jotta ongelmat huomataan, mielellään ennen kuin käyttäjät huomaavat.","also":["monitorointi","monitoring"]},{"id":"observability","g":"run","word":"Havaittavuus","text":"Kuinka hyvin järjestelmän sisällä tapahtuvaa voi päätellä ulkopuolelta sen lokien, lukujen ja jälkien avulla.","also":["observability","o11y","havaittavuus","havaittavuuden"]},{"id":"log","g":"run","word":"Loki","text":"Jatkuva päiväkirja, jota ohjelma pitää siitä, mitä se tekee, ja jonka avulla selvitetään, mikä meni pieleen.","also":["lokit","lokitus","logs","log","logging","lokin","lokia"],"noTip":1},{"id":"trace","g":"run","word":"Jälki (trace)","text":"Tallenne, joka näyttää askel askeleelta, miten yksi pyyntö kulkee järjestelmän eri osien läpi ja missä se hidastui.","also":["trace","traces","tracing","jäljitys"]},{"id":"latency","g":"run","word":"Viive (latency)","text":"Kuinka kauan kestää, ennen kuin jokin vastaa, kuten odotus napsautuksen ja sivun ilmestymisen välillä.","also":["latency","latenssi"]},{"id":"alert","g":"run","word":"Hälytys","text":"Automaattinen viesti siitä, että jokin vaatii huomiota, esimerkiksi siitä, että verkkosivusto ei vastaa.","also":["hälytykset","ilmoitus","alert","alerts","alerting","hälytyksen"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Hälytysväsymys","text":"Kun hälytyksiä on niin paljon, että ihmiset alkavat ohittaa ne, myös tärkeät.","also":["alert fatigue","alarm fatigue","hälytysuupumus","hälytysväsymys"]},{"id":"dashboard","g":"run","word":"Kojelauta","text":"Näkymä, joka näyttää tärkeimmät luvut ja tilat yhdellä silmäyksellä.","also":["dashboard","dashboards","kojetaulu","kojelaudan"],"noTip":1},{"id":"paging","g":"run","word":"Hälyttäminen päivystäjälle (paging)","text":"Päivystäjälle soittaminen tai hänen herättämisensä kiireellisesti ongelman takia.","also":["paging","paged","hälytys päivystäjälle"]},{"id":"escalation","g":"run","word":"Eskalointi","text":"Asian siirtäminen jollekulle, jolla on enemmän osaamista tai valtuuksia, kun sitä ei saada hoidettua nykyisellä tasolla tai riittävän nopeasti.","also":["eskaloida","eskaloitu","escalation","escalate","escalated","eskaloinnin"]},{"id":"triage","g":"run","word":"Triage","text":"Saapuvien asioiden nopea lajittelu kiireellisyyden ja tärkeyden mukaan, jotta pahin hoidetaan ensin.","also":["triagointi","triaged","kiireellisyysluokittelu","triagen"]},{"id":"impact","g":"run","word":"Vaikutus (impact)","text":"Kuinka paljon jokin vaikuttaa ihmisiin: kuinka moneen ja kuinka pahasti.","noTip":1},{"id":"urgency","g":"run","word":"Kiireellisyys","text":"Kuinka nopeasti jokin täytyy hoitaa. Vaikutus ja kiireellisyys yhdessä määräävät prioriteetin.","noTip":1},{"id":"plevels","g":"run","word":"Prioriteettitasot (P1, P2…)","text":"Merkinnät sille, kuinka kiireellinen asia on. P1 on vakavin ja vaatii toimia heti.","also":["P1","P2","P3","P4","priority levels","prioriteettitaso","prioriteettitasot"]},{"id":"queue","g":"run","word":"Tikettijono","text":"Lista pyynnöistä ja häiriöistä, jotka odottavat, että joku ottaa ne käsittelyyn.","also":["tikettijonot","tikettijonon","tikettijonossa","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Ensimmäinen ja toinen taso","text":"Tukitasot: ensimmäinen taso ottaa puhelun vastaan ja ratkaisee yksinkertaiset asiat; toisella tasolla on syvempää osaamista vaikeampiin. Kutsutaan myös tasoiksi 1 ja 2.","also":["1. linja","2. linja","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Häiriönhallintavastaava (incident commander)","text":"Yksi henkilö, joka johtaa häiriöön reagointia, jotta kaikki tietävät, kuka päättää ja kuka tekee mitä.","also":["häiriöpäällikkö","incident commander","incident commanders","häiriönhallintavastaava"]},{"id":"responsetime","g":"run","word":"Vasteaika","text":"Kuinka kauan kestää, ennen kuin joku ensimmäisen kerran tarttuu pyyntöön tai häiriöön.","also":["vasteajat","response time","response times","vasteajan"]},{"id":"resolution","g":"run","word":"Ratkaisuaika","text":"Kuinka kauan kestää selvittää pyyntö tai häiriö kokonaan, ilmoituksesta korjaukseen.","also":["ratkaisuajat","resolution time","resolution times","time to resolve","ratkaisuajan"]},{"id":"mttr","g":"run","word":"Keskimääräinen palautumisaika (MTTR)","text":"Kuinka kauan keskimäärin kestää saada palvelu taas toimimaan vian jälkeen. MTTR voi tarkoittaa hieman eri asioita, joten kerro, mitä mittaat.","also":["MTTR","mean time to recover","mean time to restore"]},{"id":"mtbf","g":"run","word":"Keskimääräinen aika vikojen välillä (MTBF)","text":"Kuinka kauan palvelu keskimäärin toimii, ennen kuin jokin rikkoutuu.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Konfiguraatiotietokanta (CMDB)","text":"Luettelo kaikista konfiguraatiokohteistasi ja siitä, miten ne liittyvät toisiinsa, jotta näet, mikä riippuu mistä.","also":["CMDB","configuration management database","konfiguraatiotietokanta"]},{"id":"asset","g":"run","word":"Omaisuuserä (asset)","text":"Mikä tahansa arvokas, minkä omistat tai josta maksat palvelun pyörittämiseksi, kuten kannettava, ohjelmistolisenssi tai verkkotunnus.","also":["omaisuus","asset","assets","resurssi","omaisuuserä","omaisuuserät"],"noTip":1},{"id":"capplan","g":"run","word":"Kapasiteettisuunnittelu","text":"Sen varmistaminen, että laskentatehoa, tallennustilaa ja ihmisiä on tarpeeksi sille, mitä on tulossa.","also":["kapasiteettisuunnitelma","capacity planning","capacity plan","kapasiteettisuunnittelun"]},{"id":"scaling","g":"run","word":"Skaalaus","text":"Useampien käyttäjien kanssa pärjääminen antamalla koneelle lisää tehoa (skaalaus ylöspäin) tai lisäämällä koneita (skaalaus ulospäin).","also":["skaalata","skaalaus ylöspäin","skaalaus ulospäin","scaling","scale up","scale out","scaling up","scaling out","skaalauksen"]},{"id":"bcp","g":"run","word":"Liiketoiminnan jatkuvuus","text":"Suunnitelmat siitä, miten tärkeimmät asiat pidetään käynnissä, kun jotain isoa menee pieleen, kuten toimisto, tärkeä toimittaja tai tietokoneet menetetään.","also":["jatkuvuussuunnitelma","business continuity","business continuity plan","liiketoiminnan jatkuvuuden"]},{"id":"dr","g":"run","word":"Palautuminen suurhäiriöstä (DR)","text":"Suunnitelma ja työkalut palvelun palauttamiseksi vakavan tapahtuman jälkeen, kuten kun koko konesali menetetään.","also":["DR","katastrofipalautus","disaster recovery"]},{"id":"rto","g":"run","word":"Palautumisaikatavoite (RTO)","text":"Pisin aika, jonka palvelu saa olla alhaalla katastrofin jälkeen, ennen kuin sen täytyy toimia taas.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Palautuspistetavoite (RPO)","text":"Kuinka paljon tuoreinta dataa sinulla on varaa menettää, mitattuna ajassa. Tunnin RPO tarkoittaa varmuuskopioita vähintään tunnin välein.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Redundanssi","text":"Varalaitteiden pitäminen valmiina, kuten toinen palvelin, jotta yksi vika ei pysäytä palvelua.","also":["kahdennus","kahdentaminen","redundanssin","varajärjestelmä","redundancy"]},{"id":"failover","g":"run","word":"Vikasiirtymä (failover)","text":"Automaattinen siirtyminen varajärjestelmään, kun tavallinen pettää.","also":["failover","fail over","vikasiirto","vikasiirtymä"]},{"id":"spof","g":"run","word":"Yksittäinen vikaantumispiste","text":"Yksi osa, joka kaataa kaiken mukanaan hajotessaan, koska varalla ei ole toista.","also":["single point of failure","single points of failure","SPOF","yksittäinen vikaantumispiste","yksittäisen vikaantumispisteen"]},{"id":"maintwin","g":"run","word":"Huoltoikkuna","text":"Suunniteltu ajankohta, jolloin palvelu voi olla tauolla tai hidas ylläpidon vuoksi, ilmoitettuna käyttäjille etukäteen.","also":["huoltokatko","suunniteltu huolto","maintenance window","maintenance windows","planned maintenance","huoltoikkunan","huoltoikkunat"]},{"id":"handover","g":"run","word":"Luovutus","text":"Työn, tiedon ja vastuun siirtäminen toiselle henkilölle tai tiimille, jotta mikään ei jää hoitamatta.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"Tietopankki","text":"Kokoelma ohjeartikkeleita ja vastauksia käyttäjille ja tiimille.","also":["tietopankit","tietopankin","tietämyskanta","ohjeartikkelit","knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Asiakastyytyväisyys (CSAT)","text":"Käyttäjien antama pistemäärä siitä, kuinka tyytyväisiä he olivat, usein kysytään pyynnön sulkemisen jälkeen.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Toimittaja","text":"Ulkopuolinen yritys, johon luotat, kuten palvelintilasi tarjoaja. Kutsutaan myös vendoriksi tai kolmanneksi osapuoleksi.","also":["toimittajat","kolmas osapuoli","supplier","suppliers","vendor","vendors","third party","toimittajan","toimittajaa"],"noTip":1},{"id":"retire","g":"run","word":"Palvelun alasajo","text":"Palvelun sammuttaminen pysyvästi ja hallitusti: käyttäjille kerrotaan, tiedot ja käyttöoikeudet hoidetaan ja kulut lopetetaan.","also":["palvelun lopettaminen","service retirement","retiring a service","palvelun alasajo"]},{"id":"eol","g":"run","word":"Elinkaaren loppu (EOL)","text":"Kun tuote ei enää saa päivityksiä tai tukea valmistajaltaan, joten se pitäisi korvata.","also":["EOL","end of life","end-of-life","tuen päättyminen","elinkaaren loppu"]},{"id":"cybersec","g":"sec","word":"Kyberturvallisuus","text":"Järjestelmien ja tietojen suojaaminen murroilta, varkauksilta ja vahingoittamiselta.","also":["tietoturva","kyberturva","cybersecurity","cyber security","kyberturvallisuuden"]},{"id":"authn","g":"sec","word":"Tunnistautuminen","text":"Sen tarkistaminen, kuka joku on, yleensä salasanalla tai koodilla. Usein lyhennetään authn.","also":["authn","authentication","todentaminen","tunnistautuminen","tunnistautumisen"]},{"id":"authz","g":"sec","word":"Valtuutus","text":"Sen tarkistaminen, mitä jonkun sallitaan tehdä, kun tiedät, kuka hän on. Usein lyhennetään authz.","also":["authz","authorisation","authorization","käyttöoikeuksien hallinta","valtuutus","valtuutuksen"]},{"id":"mfa","g":"sec","word":"Monivaiheinen tunnistautuminen (MFA)","text":"Kirjautuminen kahdella tai useammalla todisteella, kuten salasanalla ja puhelimeen tulevalla koodilla. Kutsutaan myös kaksivaiheiseksi tunnistautumiseksi (2FA).","also":["MFA","2FA","kaksivaiheinen tunnistautuminen","two-factor","two-factor authentication","monivaiheisen tunnistautumisen"]},{"id":"sso","g":"sec","word":"Kertakirjautuminen (SSO)","text":"Kirjautuminen kerran, jotta pääsee moneen järjestelmään, kuten työtilin käyttäminen kaikkialla.","also":["SSO","single sign-on","single sign on","kertakirjautuminen","kertakirjautumisen"]},{"id":"pwmgr","g":"sec","word":"Salasanamanageri","text":"Sovellus, joka luo vahvoja salasanoja ja muistaa ne puolestasi.","also":["salasanamanagerit","salasanamanagerin","salasanahallinta","salasanojen hallinta","password manager","password managers"]},{"id":"secret","g":"sec","word":"Salaisuus (secret)","text":"Salasana, avain tai muu yksityinen koodi, jolla ohjelma pääsee johonkin sisään. Sitä ei saa koskaan jakaa eikä kirjoittaa koodiin.","also":["salaisuudet","secret","secrets","salaisuuden"],"noTip":1},{"id":"apikey","g":"sec","word":"API-avain","text":"Salainen koodi, jonka avulla ohjelma voi käyttää toisen palvelun rajapintaa ja joka kertoo, kuka sitä käyttää (ja maksaa siitä).","also":["API-avaimet","API key","API keys","API-avaimen","API-avainta"]},{"id":"accesstoken","g":"sec","word":"Käyttötunniste (access token)","text":"Väliaikainen pääsylippu, joka todistaa, että ohjelma saa tulla sisään, jotta sen ei tarvitse kysyä salasanaasi joka kerta. Ei sama asia kuin tekoälyn token.","also":["access token","access tokens","pääsytunniste","käyttötunniste","käyttötunnisteen"]},{"id":"encryption","g":"sec","word":"Salaus","text":"Tiedon sekoittaminen niin, että vain oikean avaimen haltija voi lukea sen.","also":["salata","salattu","salaaminen","encryption","encrypted","encrypt","salauksen"]},{"id":"https","g":"sec","word":"HTTPS","text":"Turvallinen tapa siirtää verkkosivuja niin, ettei kukaan välissä voi lukea tai muuttaa niitä. Sen tunnistaa selaimen lukkokuvakkeesta."},{"id":"cert","g":"sec","word":"SSL/TLS-varmenne","text":"Digitaalinen henkilökortti, jonka avulla verkkosivusto voi todistaa, kuka se on, ja käyttää HTTPS:ää. Se vanhenee, joten se pitää uusia.","also":["TLS-varmenne","SSL-varmenne","varmenne","varmenteet","TLS certificate","SSL certificate","certificate","certificates","varmenteen","varmennetta"]},{"id":"permissions","g":"sec","word":"Käyttöoikeudet","text":"Säännöt siitä, kuka saa nähdä tai muuttaa mitä.","also":["käyttöoikeus","oikeudet","lupa","luvat","permissions","permission","käyttöoikeuksien","käyttöoikeuksia"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Vähimmän oikeuden periaate","text":"Jokaiselle ihmiselle tai ohjelmalle annetaan vain se pääsy, joka todella tarvitaan, ja vain niin pitkäksi aikaa kuin sitä tarvitaan.","also":["vähimmät oikeudet","least privilege","principle of least privilege","vähimmän oikeuden periaate"]},{"id":"rbac","g":"sec","word":"Roolipohjainen käyttöoikeuksien hallinta (RBAC)","text":"Pääsyn antaminen roolin mukaan, kuten katselija tai muokkaaja, sen sijaan että oikeudet annettaisiin henkilö kerrallaan.","also":["RBAC","roolipohjainen pääsy","role-based access control","role-based access","roolipohjainen käyttöoikeuksien hallinta"]},{"id":"vuln","g":"sec","word":"Haavoittuvuus","text":"Heikkous, jota joku voisi käyttää murtautumiseen tai vahingon tekemiseen.","also":["haavoittuvuudet","vulnerability","vulnerabilities","haavoittuvuuden","haavoittuvuutta"]},{"id":"zeroday","g":"sec","word":"Zero-day (nollapäivähaavoittuvuus)","text":"Heikkous, josta hyökkääjät tietävät ennen kuin tekijät ovat ehtineet korjata sitä lainkaan.","also":["zero-day","zero-days","zero day","nollapäivähaavoittuvuus"]},{"id":"malware","g":"sec","word":"Haittaohjelma","text":"Haitallinen ohjelmisto, kuten virukset, joka on tehty vahingoittamaan, vakoilemaan tai varastamaan.","also":["haittaohjelmat","malware","tietokonevirus","haittaohjelman","haittaohjelmia"]},{"id":"ransomware","g":"sec","word":"Kiristyshaittaohjelma (ransomware)","text":"Haittaohjelma, joka lukitsee tiedostosi ja vaatii rahaa niiden avaamisesta. Hyvät varmuuskopiot ovat paras puolustus.","also":["ransomware","kiristysohjelma","kiristyshaittaohjelma","ransomware attack","kiristyshyökkäys"]},{"id":"phishing","g":"sec","word":"Tietojenkalastelu (phishing)","text":"Valeviestejä, joilla yritetään huijata sinut luovuttamaan salasanoja tai rahaa tai avaamaan jotain haitallista.","also":["phishing","kalastelu","kalasteluviesti","phishing email","phishing emails","tietojenkalastelu","tietojenkalastelun"]},{"id":"socialeng","g":"sec","word":"Sosiaalinen manipulointi (social engineering)","text":"Ihmisten (eikä tietokoneiden) huijaaminen antamaan pääsy johonkin, esimerkiksi tekaistu puhelu ”IT-tuesta”."},{"id":"firewall","g":"sec","word":"Palomuuri","text":"Vartija, joka päättää, mikä verkkoliikenne saa tulla sisään tai mennä ulos.","also":["palomuurit","firewall","firewalls","palomuurin"]},{"id":"vpn","g":"sec","word":"VPN","text":"Lyhenne sanoista virtual private network: yksityinen, salattu yhteys internetin yli, jolla usein päästään turvallisesti työjärjestelmiin.","also":["virtuaalinen erillisverkko","virtual private network"]},{"id":"ddos","g":"sec","word":"Palvelunestohyökkäys (DoS, DDoS)","text":"Palvelun hukuttaminen niin suureen määrään valeliikennettä, etteivät oikeat ihmiset voi käyttää sitä. DDoS tarkoittaa, että liikenne tulee monelta koneelta yhtä aikaa.","also":["DoS","DDoS","DDoS-hyökkäys","palvelunesto","denial of service","DDoS attack","palvelunestohyökkäyksen"]},{"id":"pentest","g":"sec","word":"Tunkeutumistestaus (pentest)","text":"Ystävällismielisten asiantuntijoiden palkkaaminen yrittämään murtautumista, jotta heikkoudet löytyvät ennen kuin oikeat hyökkääjät löytävät ne.","also":["pentest","pen test","pen testing","penetration testing","penetraatiotestaus","tunkeutumistestaus","tunkeutumistestauksen"]},{"id":"audit","g":"sec","word":"Tietoturvatarkastus","text":"Huolellinen tarkistus siitä, kuinka hyvin jokin on suojattu, verrattuna hyvien käytäntöjen listaan.","also":["tietoturva-auditointi","tietoturvaauditointi","security audit","security audits","tietoturvatarkastuksen"]},{"id":"threatmodel","g":"sec","word":"Uhkamallinnus","text":"Sen pohtiminen, kuka voisi hyökätä jonkin kimppuun ja miten, ja mitä tekisit hyökkäyksen pysäyttämiseksi.","also":["uhkamalli","threat modelling","threat model","threat modeling","uhkamallinnuksen"]},{"id":"breach","g":"sec","word":"Tietomurto","text":"Kun yksityisiä tietoja päätyy ihmisille, joilla ei pitäisi olla niitä, tai ne katoavat tai muuttuvat luvatta.","also":["tietovuoto","tietoturvaloukkaus","data breach","data breaches","tietomurron","tietomurrot"]},{"id":"pii","g":"sec","word":"Henkilötiedot","text":"Kaikki tieto tunnistettavissa olevasta henkilöstä, kuten nimi, sähköpostiosoite tai sijainti. Kutsutaan myös PII:ksi.","also":["henkilötieto","PII","personal data","personally identifiable information","henkilötietojen","henkilötietoja"]},{"id":"gdpr","g":"sec","word":"GDPR (tietosuoja-asetus)","text":"EU:n laki henkilötiedoista (Isolla-Britannialla on oma versionsa): kerää vain tarvitsemasi, pidä ne turvassa ja anna ihmisten nähdä tai poistaa omansa.","also":["GDPR","tietosuoja-asetus","yleinen tietosuoja-asetus","General Data Protection Regulation","tietosuoja-asetuksen"]},{"id":"dataprot","g":"sec","word":"Tietosuoja","text":"Henkilötietojen asianmukainen ja lain mukainen käsittely.","also":["tietosuojalaki","data protection","data protection law","tietosuojan"]},{"id":"privacypolicy","g":"sec","word":"Tietosuojaseloste","text":"Julkinen sivu, joka kertoo, mitä henkilötietoja keräät, miksi ja mitä niillä teet.","also":["tietosuojakäytäntö","tietosuojaseloste","privacy policy","privacy statement","privacy notice","tietosuojaselosteen"]},{"id":"consent","g":"sec","word":"Suostumus","text":"Ihmisen selkeä ja vapaaehtoinen lupa siihen, että hänen tietojaan käytetään tietyllä tavalla. Sen voi perua milloin tahansa.","also":["suostumus","opt-in","consent","suostumuksen"],"noTip":1},{"id":"cookie","g":"sec","word":"Eväste (cookie)","text":"Pieni tiedosto, jonka verkkosivusto tallentaa selaimeesi muistaakseen asioita, kuten että olet kirjautunut. Joihinkin tarvitaan ensin suostumuksesi.","also":["evästeet","cookie","cookies","evästeen","evästeitä"],"noTip":1},{"id":"minimisation","g":"sec","word":"Tietojen minimointi","text":"Vain sellaisten henkilötietojen kerääminen ja säilyttäminen, joita todella tarvitaan työhön.","also":["tietojen minimointi","data minimisation","data minimization","tietojen minimoinnin"]},{"id":"retention","g":"sec","word":"Tietojen säilytysaika","text":"Kuinka kauan tietoja säilytetään ennen kuin ne poistetaan. Niiden säilyttäminen vain niin kauan kuin on tarpeen on turvallisempaa ja usein lain vaatimaa.","also":["säilytysaika","säilytysjakso","data retention","retention period","säilytysajan"]},{"id":"anon","g":"sec","word":"Anonymisointi","text":"Tietojen muuttaminen niin, ettei niistä voi enää kohtuudella tunnistaa ketään.","also":["anonymisoitu","anonyymit tiedot","anonymisation","anonymised","anonymization","anonymous data","anonymisoinnin"]},{"id":"pseudo","g":"sec","word":"Pseudonymisointi","text":"Nimien ja muiden tietojen vaihtaminen koodeihin niin, että avain, jolla ne yhdistetään takaisin, säilytetään erillään. Tiedot ovat silti yhä henkilötietoja.","also":["pseudonymisoitu","pseudonymisation","pseudonymised","pseudonymization","pseudonymisoinnin"]},{"id":"dpa","g":"sec","word":"Henkilötietojen käsittelysopimus (DPA)","text":"Sopimus, joka kertoo, miten toimittaja saa käsitellä henkilötietoja puolestasi.","also":["DPA","käsittelysopimus","data processing agreement","käsittelysopimuksen"]},{"id":"dpia","g":"sec","word":"Tietosuojan vaikutustenarviointi (DPIA)","text":"Huolellinen arvio ennen aloittamista siitä, miten henkilötietojen käyttösuunnitelma voisi vaikuttaa ihmisiin ja miten riskejä voi pienentää.","also":["DPIA","vaikutustenarviointi","data protection impact assessment","vaikutustenarvioinnin"]},{"id":"auditlog","g":"sec","word":"Auditointiloki","text":"Kirjaus siitä, kuka teki mitä ja milloin, jotta toimet voi tarkistaa myöhemmin.","also":["tarkastusloki","audit log","audit logs","audit trail","auditointiloki","auditointilokin"]},{"id":"compliance","g":"sec","word":"Vaatimustenmukaisuus (compliance)","text":"Sinuun sovellettavien lakien, sääntöjen ja standardien noudattaminen ja kyky osoittaa, että noudatat niitä.","also":["compliance","compliant","vaatimustenmukaisuus","vaatimustenmukaisuuden"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Tunnettu kansainvälinen standardi tietoturvan hallintaan. Yritykset voivat saada sen mukaisen sertifikaatin.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Yhdysvaltalainen raportti, jonka ulkopuoliset tarkastajat ovat tarkistaneet ja joka osoittaa, että yritys huolehtii asiakastiedoista kunnolla.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agentti","text":"Tekoäly, joka työskentelee tehtävän parissa itsenäisesti: lukee koodin, tekee muutokset, ajaa tarkistukset ja raportoi takaisin. Sen työ tarkistetaan silti.","also":["agentit","agentin","agenttia","agent","agents"]},{"id":"token","g":"ai","word":"Token","text":"Pienet tekstinpalat, joita tekoäly lukee ja kirjoittaa, kukin noin kolme neljäsosaa sanasta. Tekoälyn käyttö lasketaan tokeneina, joten mitä vähemmän tokeneita kuluu, sitä enemmän tilauksestasi jää jäljelle.","also":["tokenit","tokenia","tokenin","tokens"]},{"id":"hook","g":"ai","word":"Koukku","text":"Pieni komento, joka käynnistyy automaattisesti tiettynä hetkenä, esimerkiksi kun tekoälyistunto alkaa, jotta tiimi kuulee kommenttisi.","also":["koukut","hook","hooks"]},{"id":"ai","g":"ai","word":"Tekoäly (AI)","text":"Tietokonejärjestelmät, jotka tekevät asioita, joihin tavallisesti ajattelemme tarvittavan ihmistä, kuten kirjoittavat, vastaavat kysymyksiin tai tunnistavat kuvia.","also":["AI","tekoäly","artificial intelligence","tekoälyn","tekoälyä"],"noTip":1},{"id":"ml","g":"ai","word":"Koneoppiminen (ML)","text":"Tapa saada tietokoneet oppimaan kaavoja monista esimerkeistä sen sijaan, että niille annettaisiin tarkat säännöt.","also":["ML","koneoppiminen","machine learning","koneoppimisen"]},{"id":"model","g":"ai","word":"Malli","text":"Tekoälyjärjestelmän koulutetut ”aivot”, jotka on rakennettu oppimalla valtavasta määrästä esimerkkejä. Mallit eroavat taidoiltaan, nopeudeltaan ja hinnaltaan.","also":["mallit","tekoälymalli","model","models","AI model","mallin","mallia"],"noTip":1},{"id":"llm","g":"ai","word":"Suuri kielimalli (LLM)","text":"Valtavilla tekstimäärillä koulutettu tekoälymalli, joka osaa lukea ja kirjoittaa kieltä.","also":["LLM","LLM:t","kielimalli","kielimallit","LLMs","suuri kielimalli","kielimallin"]},{"id":"genai","g":"ai","word":"Generatiivinen tekoäly","text":"Tekoäly, joka luo uutta, kuten tekstiä, kuvia tai koodia, eikä vain lajittele tai tunnista asioita.","also":["GenAI","generatiivinen AI","generative AI","generatiivinen tekoäly","generatiivisen tekoälyn"]},{"id":"chatbot","g":"ai","word":"Chatbotti","text":"Ohjelma, jonka kanssa keskustelet arkikielellä kirjoittamalla tai puhumalla.","also":["chatbot","chatbotit","chatbotin","keskustelurobotti","chatbots"]},{"id":"prompt","g":"ai","word":"Kehote (prompt)","text":"Se, mitä annat tekoälylle: kysymyksesi tai ohjeesi sekä kaikki muu, mitä liität mukaan. Selkeämmät kehotteet tuottavat yleensä parempia vastauksia.","also":["kehotteet","prompt","prompts","kehotteen","kehotetta"]},{"id":"prompteng","g":"ai","word":"Kehotesuunnittelu (prompt engineering)","text":"Taito kirjoittaa kehotteita, jotka tuottavat luotettavia, hyödyllisiä tuloksia.","also":["prompt engineering","promptaus","kehotesuunnittelu"]},{"id":"sysprompt","g":"ai","word":"Järjestelmäkehote","text":"Taustaohjeet, jotka tekoäly saa ennen keskustelun alkua ja jotka asettavat sen roolin ja säännöt. Ne painavat enemmän kuin se, mitä kirjoitat.","also":["järjestelmäkehotteet","järjestelmäohje","system prompt","system prompts","system instruction","system instructions","järjestelmäkehotteen"]},{"id":"context","g":"ai","word":"Konteksti","text":"Kaikki, minkä tekoäly näkee työskennellessään: ohjeet, viestisi, lukemansa tiedostot ja aiemmat vastaukset.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontekstiikkuna","text":"Kuinka paljon tekoäly voi pitää mielessä kerralla, mitattuna tokeneina. Kun raja ylittyy, vanhempia osia pudotetaan pois tai tiivistetään.","also":["kontekstiikkunat","context window","context windows","kontekstiikkunan"]},{"id":"session","g":"ai","word":"Istunto","text":"Yksi työkeskustelu tekoälyn kanssa alusta loppuun. Uusi istunto alkaa puhtaalla muistilla.","also":["istunnot","sessio","session","sessions","istunnon","istuntoa"],"noTip":1},{"id":"memory","g":"ai","word":"Muisti","text":"Muistiinpanot, jotka tekoäly säilyttää istuntojen välillä, jotta se muistaa mieltymyksesi ja aiemmat päätökset.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallusinaatio","text":"Kun tekoäly sanoo jotain, mikä kuulostaa varmalta mutta on keksittyä tai väärää. Tarkista tärkeät asiat.","also":["hallusinaatiot","hallusinoida","hallusinoi","hallucination","hallucinations","hallucinate","hallucinates","hallusinaation"]},{"id":"training","g":"ai","word":"Koulutus","text":"Mallin opettaminen näyttämällä sille valtavasti esimerkkejä ennen kuin kukaan käyttää sitä.","also":["kouluttaminen","koulutettu","training","trained","koulutuksen"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Koulutusdata","text":"Esimerkit, joista malli oppi. Sen tieto loppuu siihen päivään, jolloin data kerättiin.","also":["koulutusaineisto","training data","training set","koulutusdata","koulutusdatan"]},{"id":"cutoff","g":"ai","word":"Tietojen katkaisupäivä (knowledge cutoff)","text":"Päivä, johon tekoälyn sisäänrakennettu tieto päättyy. Se ei tiedä myöhemmistä asioista, ellei se hae niitä.","also":["knowledge cutoff","training cutoff","tietopäivä"]},{"id":"finetune","g":"ai","word":"Hienosäätö","text":"Olemassa olevan mallin lisäkoulutus omilla esimerkeilläsi, jotta siitä tulee parempi yhdessä tietyssä työssä.","also":["fine-tuning","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Päättely (inference)","text":"Tekoälymallin varsinainen käyttö, kun se vastaa johonkin, erotuksena sen kouluttamisesta.","also":["inference","model inference","mallin ajo"]},{"id":"tooluse","g":"ai","word":"Työkalujen käyttö","text":"Se, että tekoäly voi tehdä asioita eikä vain puhua: ajaa komentoja, lukea tiedostoja tai hakea verkosta, sovelluksen antamien työkalujen kautta.","also":["työkalukutsu","tool use","tool calling","tool call","tool calls","työkalujen käyttö","työkalukutsut"]},{"id":"subagent","g":"ai","word":"Aliagentti","text":"Apulaistekoäly, jolle päätekoäly antaa pienemmän tehtävän ja jolta se saa tuloksen takaisin.","also":["aliagentit","subagent","subagents","sub-agent","aliagentin","aliagenttia"]},{"id":"multiagent","g":"ai","word":"Moniagenttinen","text":"Useat tekoälyt työskentelevät yhdessä saman työn parissa, kullakin oma osansa, kuin pieni tiimi.","also":["moniagenttijärjestelmä","multi-agent","multi-agent system","moniagenttinen"]},{"id":"autonomy","g":"ai","word":"Autonomia","text":"Kuinka paljon tekoäly saa tehdä omin päin, ennen kuin sen täytyy kysyä ihmiseltä.","also":["autonominen","autonomy","autonomous","autonomian"]},{"id":"hitl","g":"ai","word":"Ihminen mukana silmukassa","text":"Ihmisen pitäminen mukana tarkistamassa tai hyväksymässä, mitä tekoäly tekee tärkeissä kohdissa. AI-gilessä se olet sinä.","also":["human in the loop","human-in-the-loop","HITL","ihminen silmukassa"]},{"id":"guardrails","g":"ai","word":"Suojakaiteet (guardrails)","text":"Rajat ja tarkistukset, jotka pitävät tekoälyn toimet turvallisina, kuten hyväksynnän vaatiminen ennen kuin mitään julkaistaan. Ne vähentävät virheiden riskiä mutta eivät sulje niitä pois.","also":["guardrails","guardrail","suojakaide","suojakaiteet"]},{"id":"rag","g":"ai","word":"Hakuun perustuva generointi (RAG)","text":"Tekoäly saa hakea tietoa omista dokumenteistasi ennen kuin se vastaa, jotta sen vastaukset perustuvat sinun tietoihisi.","also":["RAG","retrieval-augmented generation","retrieval augmented generation","hakuun perustuva generointi"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Tekstin muuttaminen numerolistaksi, joka tallentaa sen merkityksen, jotta tietokone löytää asioita, joilla on samankaltainen merkitys.","also":["embeddings","vektoriesitys","embedding","embeddingin"]},{"id":"vectordb","g":"ai","word":"Vektoritietokanta","text":"Tietokanta, joka on tehty hakemaan näistä numerolistoista (embeddingeistä) sisältöä, jolla on samankaltainen merkitys.","also":["vektoritietokannat","vector database","vector databases","vector store","vektoritietokannan"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Yhteinen tapa liittää työkaluja ja tietolähteitä tekoälysovelluksiin, jotta tekoäly voi käyttää niitä.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Lämpötila (temperature)","text":"Asetus siitä, kuinka seikkailunhaluisia tekoälyn vastaukset ovat. Matala antaa tasaisempia ja ennustettavampia vastauksia, korkea vaihtelevampia. Kumpikaan ei takaa, että vastaus on aina oikein.","also":["temperature","mallin lämpötila","model temperature","lämpötilan"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodaalinen","text":"Osaa käsitellä useampaa kuin yhtä tietolajia, kuten tekstiä, kuvia ja ääntä.","also":["multi-modal","multimodaalisuus","multimodaalinen"]},{"id":"evals","g":"ai","word":"Arviointi (eval)","text":"Suunniteltu testi siitä, kuinka hyvin tekoäly pärjää valituilla esimerkeillä, jotta voit verrata malleja tai kehotteita.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Vinouma (bias)","text":"Kun tekoäly (tai ihminen) kallistuu epäreilusti yhteen suuntaan, usein sen takia, mistä se on oppinut.","also":["bias","biased","ennakkoluulo","puolueellisuus","vinouman","vinoumaa"],"noTip":1},{"id":"responsible","g":"ai","word":"Vastuullinen tekoäly","text":"Tekoälyn käyttö reilusti, turvallisesti ja rehellisesti, niin että ihmiset ovat edelleen vastuussa tuloksista.","also":["eettinen tekoäly","vastuullinen AI","responsible AI","ethical AI","vastuullisen tekoälyn"]},{"id":"injection","g":"ai","word":"Kehotteen injektio (prompt injection)","text":"Temppu, jossa verkkosivun tai tiedoston piilotetut ohjeet yrittävät saada tekoälyn tekemään jotain, mitä sen käyttäjä ei pyytänyt.","also":["prompt injection","prompt injections","kehoteinjektio","kehotteen injektio"]},{"id":"ratelimit","g":"ai","word":"Pyyntöraja (rate limit)","text":"Yläraja sille, kuinka monta pyyntöä voit lähettää palvelulle tietyssä ajassa. Jos ylität sen, sinun täytyy odottaa.","also":["pyyntöraja","pyyntörajat","pyyntörajan","rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Käyttöraja","text":"Kuinka paljon tekoälytyötä tilauksesi sallii tietyn jakson aikana, minkä jälkeen se pysähtyy tai maksaa enemmän.","also":["käyttörajat","usage limit","usage limits","käyttörajan","käyttörajaa"]},{"id":"vibe","g":"ai","word":"Vibe-koodaus","text":"Ohjelmiston tekeminen pääasiassa kuvailemalla tekoälylle, mitä haluat, ja antamalla sen kirjoittaa koodi.","also":["vibekoodaus","vibe coding","vibe-coding","vibe-koodaus"]},{"id":"budget","g":"money","word":"Budjetti","text":"Rahamäärä, joka on varattu johonkin.","also":["budjetit","budget","budgets","budjetin","budjettia"],"noTip":1},{"id":"costest","g":"money","word":"Kustannusarvio","text":"Paras arvaus siitä, mitä jokin tulee maksamaan, ennen kuin aloitat.","also":["kustannusarviot","cost estimate","cost estimates","kustannusarvion"]},{"id":"roi","g":"money","word":"Sijoitetun pääoman tuotto (ROI)","text":"Se, mitä saat takaisin verrattuna siihen, mitä laitoit siihen. Jos tulos on positiivinen, se kannatti.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Kokonaiskustannus (TCO)","text":"Kaikki, mitä jokin todella maksaa koko elinkaarensa ajan, ei vain ostohinta: käyttö, tuki, päivitykset ja lopulta käytöstä poisto.","also":["TCO","omistuskustannus","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx ja OpEx","text":"CapEx on kertaluonteista rahankäyttöä asioihin, jotka jäävät omiksesi; OpEx on jatkuvia kuluja, kuten kuukausilaskut.","also":["CapEx","OpEx","investointikulut","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Tilaus","text":"Säännöllinen maksu, yleensä kuukausittain tai vuosittain, jotta voit jatkaa jonkin käyttöä.","also":["tilaukset","kuukausitilaus","subscription","subscriptions","tilauksen"],"noTip":1},{"id":"saas","g":"money","word":"Ohjelmisto palveluna (SaaS)","text":"Ohjelmisto, jota käytät verkossa ja josta maksat tilauksella, ja jota tekijä pyörittää puolestasi.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Maksu käytön mukaan","text":"Maksaminen vain siitä, mitä todella käytät, kuten pilvipalveluissa tai tekoälyn tokeneissa.","also":["pay as you go","pay-as-you-go","käyttöön perustuva hinnoittelu","usage-based pricing","maksu käytön mukaan"]},{"id":"overage","g":"money","word":"Ylikäyttö","text":"Käyttö, joka ylittää sen, mitä tilaukseesi sisältyy, ja joka voi maksaa lisää.","also":["ylikäyttömaksu","overage","overages","overage charges","ylikäytön"]},{"id":"billingalert","g":"money","word":"Laskutushälytys","text":"Viesti, kun kulutus tai käyttö saavuttaa valitsemasi tason. Se varoittaa sinua, mutta ei aina pysäytä lisämaksuja.","also":["kulutushälytys","billing alert","billing alerts","spending alert","laskutushälytys","laskutushälytyksen"]},{"id":"freetier","g":"money","word":"Ilmainen taso","text":"Maksullisen palvelun ilmainen taso rajoituksin. Kätevä alkuvaiheessa.","also":["ilmainen paketti","free tier","free plan","ilmainen taso","ilmaisen tason"]},{"id":"pricing","g":"money","word":"Hinnoittelupaketti","text":"Eri paketit, joita palvelu myy, kullakin oma hintansa ja rajansa.","also":["hinnoittelupaketit","hinnasto","pricing plan","pricing plans","price plan","hinnoittelupaketin"]},{"id":"licence","g":"money","word":"Lisenssi","text":"Säännöt siitä, miten saat käyttää, kopioida, muuttaa tai jakaa jotain, minkä joku muu on tehnyt, kuten ohjelmistoja, fontteja tai kuvia.","also":["lisenssit","käyttöoikeus","licence","licences","license","licenses","lisenssin","lisenssiä"],"noTip":1},{"id":"opensource","g":"money","word":"Avoin lähdekoodi","text":"Ohjelmisto, jonka koodin kuka tahansa voi lukea, käyttää ja usein muuttaa ilmaiseksi lisenssin sääntöjen mukaan.","also":["avoin lähdekoodi","open source","open-source","open source software","OSS","avoimen lähdekoodin"]},{"id":"osslicence","g":"money","word":"Avoimen lähdekoodin lisenssi","text":"Säännöt, jotka tulevat avoimen lähdekoodin mukana. Jotkin sallivat melkein mitä tahansa (kuten MIT), jotkin pyytävät sinua jakamaan myös muutoksesi (kuten GPL).","also":["avoimen lähdekoodin lisenssit","MIT-lisenssi","GPL","open source licence","open source licences","MIT licence"]},{"id":"proprietary","g":"money","word":"Suljettu (proprietary)","text":"Yrityksen omistama ohjelmisto, jota ei saa vapaasti kopioida tai muuttaa. Avoimen lähdekoodin vastakohta.","also":["suljettu ohjelmisto","proprietary","proprietary software","omistettu ohjelmisto"]},{"id":"copyright","g":"money","word":"Tekijänoikeus","text":"Tekijän laillinen oikeus päättää teoksensa kopioista, myös koodista ja tekstistä.","also":["tekijänoikeudet","copyright","copyrighted","tekijänoikeuden"],"noTip":1},{"id":"ip","g":"money","word":"Immateriaalioikeudet (IP)","text":"Ideat ja luomukset, joita laki pitää omistettuina, kuten koodi, suunnitelmat, nimet ja logot.","also":["IP","immateriaalioikeus","intellectual property","immateriaalioikeuksien"]},{"id":"tos","g":"money","word":"Käyttöehdot","text":"Säännöt, joihin suostut, kun käytät palvelua.","also":["palveluehdot","käyttöehtojen","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Sopimus","text":"Kahden osapuolen välinen kirjallinen sopimus, joka on lain nojalla sitova.","also":["sopimukset","contract","contracts","sopimuksen"],"noTip":1},{"id":"sow","g":"money","word":"Työselostus (SOW)","text":"Asiakirja, joka kertoo tarkasti, mitä työtä tehdään, mihin mennessä ja millä hinnalla.","also":["SOW","statement of work","työselostus","työselostuksen"]},{"id":"fixedprice","g":"money","word":"Kiinteä hinta","text":"Sovittu hinta koko työstä, vaikka se kestäisi kuinka kauan.","also":["kiinteähintainen","fixed price","fixed-price","kiinteä hinta","kiinteän hinnan"]},{"id":"tm","g":"money","word":"Aika ja materiaali","text":"Maksaminen todella tehdyistä tunneista ja todella käytetyistä tarvikkeista kiinteän hinnan sijaan.","also":["T&M","tuntiveloitus","time and materials"]},{"id":"invoice","g":"money","word":"Lasku","text":"Maksupyyntö tehdystä työstä tai toimitetuista tavaroista.","also":["laskut","invoice","invoices","laskun"],"noTip":1},{"id":"lockin","g":"money","word":"Toimittajasidonnaisuus (lock-in)","text":"Kun toimittajasta luopuminen on niin vaikeaa tai kallista, että jäät siihen kiinni.","also":["lock-in","vendor lock-in","toimittajasidonnaisuus"]},{"id":"procurement","g":"money","word":"Hankinta","text":"Prosessi, jossa valitaan toimittajat ja ostetaan heiltä.","also":["ostotoiminta","procurement"]},{"id":"servicecredit","g":"money","word":"Palveluhyvitys","text":"Rahat takaisin tai alennus, jonka saat, kun toimittaja ei täytä palvelutasosopimustaan.","also":["palveluhyvitykset","service credit","service credits","palveluhyvityksen"]}]}};
